func tbPairLess(d *port.Cells, a int32, b int32) bool {
	// Pairs (stride 6: cell, word, baseline, x0, size, spare) in a cell's reading order: by cell, then
	// by baseline (the same line when they differ by under a third of the size), then by x.
	var ca int32 = port.CellsAt(d, a*6)
	var cb int32 = port.CellsAt(d, b*6)
	if ca != cb {
		return ca < cb
	}
	var ya int32 = port.CellsAt(d, (a*6)+2)
	var yb int32 = port.CellsAt(d, (b*6)+2)
	var sz int32 = port.CellsAt(d, (a*6)+4)
	if (3 * tbAbs(ya-yb)) > sz {
		return ya < yb
	}
	var xa int32 = port.CellsAt(d, (a*6)+3)
	var xb int32 = port.CellsAt(d, (b*6)+3)
	if xa != xb {
		return xa < xb
	}
	return a < b
}

func tbSortPairs(ord *port.Cells, d *port.Cells) int32 {
	var n int32 = port.CellsLen(ord)
	var h int32 = 1
	var i int32 = 0
	var j int32 = 0
	var v int32 = 0
	var u int32 = 0
	var more int32 = 1
	for h < (n / 3) {
		h = (h * 3) + 1
	}
	for h >= 1 {
		i = h
		for i < n {
			v = port.CellsAt(ord, i)
			j = i
			more = 1
			for (j >= h) && (more == 1) {
				u = port.CellsAt(ord, j-h)
				if tbPairLess(d, v, u) {
					port.CellsSet(ord, j, u)
					j -= h
				} else {
					more = 0
				}
			}
			port.CellsSet(ord, j, v)
			i += 1
		}
		h = (h - 1) / 3
	}
	return 0
}

func tbPairAdd(pr *port.Cells, wd *port.Cells, cell int32, w int32) int32 {
	port.CellsPush(pr, cell)
	port.CellsPush(pr, w)
	port.CellsPush(pr, evidence.WdGet(wd, w, evidence.HdBy1()))
	port.CellsPush(pr, evidence.WdGet(wd, w, evidence.HdX0()))
	port.CellsPush(pr, tbMax(1, evidence.WdGet(wd, w, evidence.WfSize())))
	port.CellsPush(pr, 0)
	return 0
}

func tbFlushPairs(pr *port.Cells, so *port.Cells, wd *port.Cells, tc *port.Cells, tw *port.Cells) int32 {
	// Sort the pairs (cell = an absolute `tc` row, word) and append each cell's words to `tw`, setting its
	// wfirst, wcount and text extent. Cells that no pair names keep wcount 0 and an extent of nothing.
	var n int32 = tbRowsOf(pr, 6)
	var i int32 = 0
	var cur int32 = -1
	port.CellsDrop(so, 0)
	for i < n {
		port.CellsPush(so, i)
		i += 1
	}
	tbSortPairs(so, pr)
	i = 0
	for i < n {
		var p int32 = port.CellsAt(so, i)
		var cell int32 = port.CellsAt(pr, p*6)
		var w int32 = port.CellsAt(pr, (p*6)+1)
		var wx0 int32 = evidence.WdGet(wd, w, evidence.HdX0())
		var wx1 int32 = evidence.WdGet(wd, w, evidence.HdX1())
		if cell != cur {
			cur = cell
			port.CellsSet(tc, (cell*tcs)+8, port.CellsLen(tw))
			port.CellsSet(tc, (cell*tcs)+9, 0)
			port.CellsSet(tc, (cell*tcs)+13, wx0)
			port.CellsSet(tc, (cell*tcs)+14, wx1)
		}
		port.CellsPush(tw, w)
		var wcn int32 = port.CellsAt(tc, (cell*tcs)+9)
		port.CellsSet(tc, (cell*tcs)+9, wcn+1)
		if wx0 < port.CellsAt(tc, (cell*tcs)+13) {
			port.CellsSet(tc, (cell*tcs)+13, wx0)
		}
		if wx1 > port.CellsAt(tc, (cell*tcs)+14) {
			port.CellsSet(tc, (cell*tcs)+14, wx1)
		}
		i += 1
	}
	port.CellsDrop(pr, 0)
	return 0
}

func tbIndexOf(b *port.Cells, v int32) int32 {
	// The interval of the sorted boundaries b that holds v: the greatest i with b[i] <= v, and -1 when v
	// is before the first or at or after the last.
	var n int32 = port.CellsLen(b)
	var i int32 = 0
	var r int32 = -1
	if n < 2 {
		return -1
	}
	if (v < port.CellsAt(b, 0)) || (v >= port.CellsAt(b, n-1)) {
		return -1
	}
	for i < (n - 1) {
		if port.CellsAt(b, i) <= v {
			r = i
		}
		i += 1
	}
	return r
}

func tbWideCells(tc *port.Cells, cfirst int32, cend int32, wd *port.Cells, tw *port.Cells) int32 {
	// How many cells have a gap between two words of one line wider than SEG_NUM/SEG_DEN of their size: the
	// cell of a lattice with too few rules, whose columns are in the text.
	var c int32 = cfirst
	var n int32 = 0
	var k int32 = 0
	var wide int32 = 0
	for c < cend {
		wide = 0
		k = 1
		for (k < port.CellsAt(tc, (c*tcs)+9)) && (wide == 0) {
			var a int32 = port.CellsAt(tw, port.CellsAt(tc, (c*tcs)+8)+(k-1))
			var b int32 = port.CellsAt(tw, port.CellsAt(tc, (c*tcs)+8)+k)
			var sz int32 = tbMax(1, evidence.WdGet(wd, b, evidence.WfSize()))
			if tbAbs(evidence.WdGet(wd, a, evidence.HdBy1())-evidence.WdGet(wd, b, evidence.HdBy1())) <= (sz / 3) {
				if ((evidence.WdGet(wd, b, evidence.HdX0()) - evidence.WdGet(wd, a, evidence.HdX1())) * segDen) > (sz * segNum) {
					wide = 1
				}
			}
			k += 1
		}
		n += wide
		c += 1
	}
	return n
}

func tbLattice(rm *port.Cells, root int32, xs *port.Cells, ys *port.Cells, page int32, gm *port.Cells, tb *port.Cells, tc *port.Cells, wd *port.Cells, w0 int32, w1 int32, pr *port.Cells, so *port.Cells, tw *port.Cells, tx *port.Cells) int32 {
	// The cells of one component's lattice, their words, and the candidate table. Answers its index, -1
	// when it is not a table.
	var nc int32 = port.CellsLen(xs) - 1
	var nr int32 = port.CellsLen(ys) - 1
	var cfirst int32 = tbRowsOf(tc, tcs)
	var tw0 int32 = port.CellsLen(tw)
	var r int32 = 0
	var c int32 = 0
	var cs int32 = 1
	var rs int32 = 1
	var ok int32 = 1
	var cc int32 = 0
	if (nc < 2) || (nr < 2) {
		return -1
	}
	if (nc * nr) > 4000 {
		return -1
	}
	port.CellsDrop(gm, 0)
	r = 0
	for r < (nc * nr) {
		port.CellsPush(gm, -1)
		r += 1
	}
	r = 0
	for r < nr {
		c = 0
		for c < nc {
			if port.CellsAt(gm, (r*nc)+c) == -1 {
				cs = 1
				ok = 1
				for (ok == 1) && ((c + cs) < nc) {
					if (port.CellsAt(gm, ((r*nc)+c)+cs) == -1) && !tbClosed(rm, root, 1, port.CellsAt(xs, c+cs), port.CellsAt(ys, r), port.CellsAt(ys, r+1)) {
						cs += 1
					} else {
						ok = 0
					}
				}
				rs = 1
				ok = 1
				for (ok == 1) && ((r + rs) < nr) {
					cc = c
					for (ok == 1) && (cc < (c + cs)) {
						if port.CellsAt(gm, ((r+rs)*nc)+cc) == -1 {
							if tbClosed(rm, root, 0, port.CellsAt(ys, r+rs), port.CellsAt(xs, cc), port.CellsAt(xs, cc+1)) {
								ok = 0
							}
						} else {
							ok = 0
						}
						if (ok == 1) && (cc > c) {
							if tbClosed(rm, root, 1, port.CellsAt(xs, cc), port.CellsAt(ys, r+rs), port.CellsAt(ys, (r+rs)+1)) {
								ok = 0
							}
						}
						cc += 1
					}
					if ok == 1 {
						rs += 1
					}
				}
				var kc int32 = tbCellAdd(tc, r, c, rs, cs, port.CellsAt(xs, c), port.CellsAt(ys, r), port.CellsAt(xs, c+cs), port.CellsAt(ys, r+rs))
				var rr int32 = r
				for rr < (r + rs) {
					cc = c
					for cc < (c + cs) {
						port.CellsSet(gm, (rr*nc)+cc, kc)
						cc += 1
					}
					rr += 1
				}
			}
			c += 1
		}
		r += 1
	}
	port.CellsDrop(pr, 0)
	var w int32 = w0
	for w < w1 {
		var cx int32 = (evidence.WdGet(wd, w, evidence.HdX0()) + evidence.WdGet(wd, w, evidence.HdX1())) / 2
		var cy int32 = (evidence.WdGet(wd, w, evidence.HdY0()) + evidence.WdGet(wd, w, evidence.HdY1())) / 2
		var ci int32 = tbIndexOf(xs, cx)
		var ri int32 = tbIndexOf(ys, cy)
		if (ci >= 0) && (ri >= 0) {
			if evidence.WdGet(wd, w, evidence.HdTlen()) > 0 {
				tbPairAdd(pr, wd, port.CellsAt(gm, (ri*nc)+ci), w)
			}
		}
		w += 1
	}
	tbFlushPairs(pr, so, wd, tc, tw)
	var total int32 = tbRowsOf(tc, tcs) - cfirst
	var filled int32 = 0
	var k int32 = cfirst
	for k < tbRowsOf(tc, tcs) {
		if port.CellsAt(tc, (k*tcs)+9) > 0 {
			filled += 1
		}
		k += 1
	}
	if (filled < 4) || ((filled * 5) < (total * 2)) {
		port.CellsDrop(tc, cfirst*tcs)
		port.CellsDrop(tw, tw0)
		return -1
	}
	if (tbWideCells(tc, cfirst, cfirst+total, wd, tw) * 10) >= (filled * 3) {
		port.CellsDrop(tc, cfirst*tcs)
		port.CellsDrop(tw, tw0)
		return -1
	}
	var t int32 = tbAdd(tb, page, port.CellsAt(xs, 0), port.CellsAt(ys, 0), port.CellsAt(xs, nc), port.CellsAt(ys, nr), pfRuled, 900, nr, nc, cfirst, total)
	var i int32 = 0
	port.CellsSet(tb, (t*tbs)+16, port.CellsLen(tx))
	port.CellsSet(tb, (t*tbs)+17, nc+1)
	for i <= nc {
		port.CellsPush(tx, port.CellsAt(xs, i))
		i += 1
	}
	return t
}

func tbRuledPage(rm *port.Cells, page int32, xs *port.Cells, ys *port.Cells, gm *port.Cells, tb *port.Cells, tc *port.Cells, wd *port.Cells, w0 int32, w1 int32, pr *port.Cells, so *port.Cells, tw *port.Cells, tx *port.Cells) int32 {
	// Every component of the page's merged rules with two rules each way is a lattice candidate.
	var n int32 = tbRowsOf(rm, rls)
	var i int32 = 0
	var j int32 = 0
	var nh int32 = 0
	var nv int32 = 0
	tbComponents(rm)
	for i < n {
		if tbFind(rm, i) == i {
			port.CellsDrop(xs, 0)
			port.CellsDrop(ys, 0)
			nh = 0
			nv = 0
			j = 0
			for j < n {
				if tbFind(rm, j) == i {
					var pos int32 = port.CellsAt(rm, (j*rls)+1)
					var a0 int32 = port.CellsAt(rm, (j*rls)+2)
					var a1 int32 = port.CellsAt(rm, (j*rls)+3)
					if port.CellsAt(rm, j*rls) == 0 {
						nh += 1
						port.CellsPush(ys, pos)
						port.CellsPush(xs, a0)
						port.CellsPush(xs, a1)
					} else {
						nv += 1
						port.CellsPush(xs, pos)
						port.CellsPush(ys, a0)
						port.CellsPush(ys, a1)
					}
				}
				j += 1
			}
			if (nh >= 2) && (nv >= 2) {
				tbCluster(xs, 2*posTol)
				tbCluster(ys, 2*posTol)
				tbLattice(rm, i, xs, ys, page, gm, tb, tc, wd, w0, w1, pr, so, tw, tx)
			}
		}
		i += 1
	}
	return 0
}

func tbOverlap(tb *port.Cells, a int32, b int32) bool {
	// Do the boxes of candidates a and b overlap by more than a rule's width both ways.
	var ax0 int32 = port.CellsAt(tb, (a*tbs)+1)
	var ay0 int32 = port.CellsAt(tb, (a*tbs)+2)
	var ax1 int32 = port.CellsAt(tb, (a*tbs)+3)
	var ay1 int32 = port.CellsAt(tb, (a*tbs)+4)
	var bx0 int32 = port.CellsAt(tb, (b*tbs)+1)
	var by0 int32 = port.CellsAt(tb, (b*tbs)+2)
	var bx1 int32 = port.CellsAt(tb, (b*tbs)+3)
	var by1 int32 = port.CellsAt(tb, (b*tbs)+4)
	return ((tbMin(ax1, bx1) - tbMax(ax0, bx0)) > posTol) && ((tbMin(ay1, by1) - tbMax(ay0, by0)) > posTol)
}

func tbSelect(tb *port.Cells, t0 int32, so *port.Cells, vals *port.Cells, sa *port.Cells) int32 {
	// Of the candidates t0.. of one page keep, best score first, those that overlap no better one, and
	// leave them in tb in the order of their tops. Answers how many are kept.
	var n int32 = tbRowsOf(tb, tbs)
	var i int32 = t0
	var j int32 = 0
	var kept int32 = 0
	var hit int32 = 0
	port.CellsDrop(so, 0)
	port.CellsDrop(vals, 0)
	for i < n {
		port.CellsPush(so, i-t0)
		port.CellsPush(vals, 0-port.CellsAt(tb, (i*tbs)+6))
		port.CellsPush(vals, i)
		i += 1
	}
	tbSortIdx(so, vals, 2, 0, 1)
	i = 0
	for i < port.CellsLen(so) {
		var c int32 = t0 + port.CellsAt(so, i)
		hit = 0
		j = 0
		for j < i {
			var o int32 = t0 + port.CellsAt(so, j)
			if port.CellsAt(tb, (o*tbs)+13) == 1 {
				if tbOverlap(tb, c, o) {
					hit = 1
				}
			}
			j += 1
		}
		if hit == 0 {
			port.CellsSet(tb, (c*tbs)+13, 1)
			kept += 1
		} else {
			port.CellsSet(tb, (c*tbs)+13, 2)
		}
		i += 1
	}
	port.CellsDrop(so, 0)
	port.CellsDrop(vals, 0)
	i = t0
	for i < n {
		if port.CellsAt(tb, (i*tbs)+13) == 1 {
			port.CellsPush(so, port.CellsLen(vals)/2)
			port.CellsPush(vals, port.CellsAt(tb, (i*tbs)+2))
			port.CellsPush(vals, i)
		}
		i += 1
	}
	tbSortIdx(so, vals, 2, 0, 1)
	port.CellsDrop(sa, 0)
	i = 0
	for i < port.CellsLen(so) {
		var src int32 = port.CellsAt(vals, (port.CellsAt(so, i)*2)+1)
		var f int32 = 0
		for f < tbs {
			port.CellsPush(sa, port.CellsAt(tb, (src*tbs)+f))
			f += 1
		}
		i += 1
	}
	port.CellsDrop(tb, t0*tbs)
	i = 0
	for i < port.CellsLen(sa) {
		port.CellsPush(tb, port.CellsAt(sa, i))
		i += 1
	}
	return kept
}

func tbClaim(tb *port.Cells, t0 int32, ln *port.Cells, l0 int32, l1 int32) int32 {
	// Mark the lines of l0..l1 whose centre is in a kept table (t0.. of tb) with the table's index + 1.
	var n int32 = tbRowsOf(tb, tbs)
	var k int32 = t0
	var l int32 = 0
	for k < n {
		l = l0
		for l < l1 {
			var cx int32 = (evidence.LnGet(ln, l, evidence.LhX0()) + evidence.LnGet(ln, l, evidence.LhX1())) / 2
			var cy int32 = (evidence.LnGet(ln, l, evidence.LhY0()) + evidence.LnGet(ln, l, evidence.LhY1())) / 2
			if (cx >= port.CellsAt(tb, (k*tbs)+1)) && (cx <= port.CellsAt(tb, (k*tbs)+3)) {
				if (cy >= port.CellsAt(tb, (k*tbs)+2)) && (cy <= port.CellsAt(tb, (k*tbs)+4)) {
					if evidence.LnGet(ln, l, 15) == 0 {
						evidence.LnSet(ln, l, 15, k+1)
					}
				}
			}
			l += 1
		}
		k += 1
	}
	return 0
}

func tbPutProfile(text *port.Cells, prof int32) int32 {
	// The profile's name (SPEC 10.5) appended to the text arena.
	if prof == pfRuled {
		model.TextAppendCp(text, 114)
		model.TextAppendCp(text, 117)
		model.TextAppendCp(text, 108)
		model.TextAppendCp(text, 101)
		model.TextAppendCp(text, 100)
	}
	if prof == pfPartial {
		model.TextAppendCp(text, 112)
		model.TextAppendCp(text, 97)
		model.TextAppendCp(text, 114)
		model.TextAppendCp(text, 116)
		model.TextAppendCp(text, 105)
		model.TextAppendCp(text, 97)
		model.TextAppendCp(text, 108)
	}
	if prof == pfShaded {
		model.TextAppendCp(text, 115)
		model.TextAppendCp(text, 104)
		model.TextAppendCp(text, 97)
		model.TextAppendCp(text, 100)
		model.TextAppendCp(text, 101)
		model.TextAppendCp(text, 100)
	}
	if prof == pfWhitespace {
		model.TextAppendCp(text, 119)
		model.TextAppendCp(text, 104)
		model.TextAppendCp(text, 105)
		model.TextAppendCp(text, 116)
		model.TextAppendCp(text, 101)
		model.TextAppendCp(text, 115)
		model.TextAppendCp(text, 112)
		model.TextAppendCp(text, 97)
		model.TextAppendCp(text, 99)
		model.TextAppendCp(text, 101)
	}
	return 0
}

func tbWordsRaw(wd *port.Cells, et *port.Cells, tw *port.Cells, from int32, num int32, raw *port.Cells) int32 {
	// The words tw[first..first+count) as code points into `raw`: a space between two words, none after a
	// soft hyphen (which goes). `raw` is emptied first.
	var k int32 = 0
	var j int32 = 0
	var started int32 = 0
	port.CellsDrop(raw, 0)
	for k < num {
		var w int32 = port.CellsAt(tw, from+k)
		var ts int32 = evidence.WdGet(wd, w, evidence.HdTstart())
		var tl int32 = evidence.WdGet(wd, w, evidence.HdTlen())
		if (ts >= 0) && (tl > 0) {
			if started == 1 {
				var n int32 = port.CellsLen(raw)
				if (n > 0) && (port.CellsAt(raw, n-1) == 173) {
					port.CellsDrop(raw, n-1)
				} else {
					port.CellsPush(raw, 32)
				}
			}
			started = 1
			j = 0
			for j < tl {
				port.CellsPush(raw, port.CellsAt(et, ts+j))
				j += 1
			}
		}
		k += 1
	}
	return 0
}

func tbEmitCell(tb *port.Cells, k int32, c int32, row int32, wd *port.Cells, et *port.Cells, tc *port.Cells, tw *port.Cells, nodes *port.Cells, attrs *port.Cells, regions *port.Cells, text *port.Cells, raw *port.Cells, tmp *port.Cells) int32 {
	var cb int32 = c * tcs
	var page int32 = port.CellsAt(tb, k*tbs)
	var n int32 = model.NodeNew(nodes, model.NkCell(), row)
	var wc int32 = port.CellsAt(tc, cb+9)
	model.NodeSetConf(nodes, n, 600)
	model.NodeAddSrc(nodes, n, model.SrText())
	model.NodeAddSrc(nodes, n, model.SrInfer())
	if port.CellsAt(tc, cb+10) > 0 {
		model.NodeSetSub(nodes, n, port.CellsAt(tc, cb+10))
	}
	if port.CellsAt(tc, cb+2) > 1 {
		model.NodeSetAttrInt(nodes, attrs, n, model.FkRowspan(), port.CellsAt(tc, cb+2))
	}
	if port.CellsAt(tc, cb+3) > 1 {
		model.NodeSetAttrInt(nodes, attrs, n, model.FkColspan(), port.CellsAt(tc, cb+3))
	}
	if port.CellsAt(tc, cb+11) > 0 {
		model.NodeSetAlign(nodes, attrs, n, port.CellsAt(tc, cb+11))
	}
	model.NodeAddRegion(nodes, regions, n, page, port.CellsAt(tc, cb+4), port.CellsAt(tc, cb+5), port.CellsAt(tc, cb+6), port.CellsAt(tc, cb+7))
	if wc == 0 {
		model.NodeSetAux(nodes, n, 1)
	} else {
		tbWordsRaw(wd, et, tw, port.CellsAt(tc, cb+8), wc, raw)
		var t0 int32 = port.CellsLen(text)
		normalize.NzNfc(raw, 0, port.CellsLen(raw), text, tmp, normalize.NzFlagLigatures()+normalize.NzFlagRadicals())
		model.NodeSetText(nodes, n, t0, port.CellsLen(text)-t0)
	}
	return 0
}

func tbPutWord(text *port.Cells, wd *port.Cells, et *port.Cells, w int32) int32 {
	// The word's code points appended to the text arena without its trailing full stops and colons.
	var ts int32 = evidence.WdGet(wd, w, evidence.HdTstart())
	var tl int32 = evidence.WdGet(wd, w, evidence.HdTlen())
	var j int32 = 0
	for (tl > 1) && ((port.CellsAt(et, ts+(tl-1)) == 46) || (port.CellsAt(et, ts+(tl-1)) == 58)) {
		tl -= 1
	}
	for j < tl {
		model.TextAppendCp(text, port.CellsAt(et, ts+j))
		j += 1
	}
	return 0
}

func tbSeparator(wd *port.Cells, et *port.Cells, w int32) bool {
	// A word that is only a separator between a label and its text: . : - en dash em dash.
	var ts int32 = evidence.WdGet(wd, w, evidence.HdTstart())
	var tl int32 = evidence.WdGet(wd, w, evidence.HdTlen())
	if tl != 1 {
		return 0 == 1
	}
	var cp int32 = port.CellsAt(et, ts)
	return (cp == 46) || ((cp == 58) || ((cp == 45) || ((cp == 8211) || (cp == 8212))))
}

func tbEmitCaption(tb *port.Cells, k int32, wd *port.Cells, et *port.Cells, ln *port.Cells, tq *port.Cells, t int32, nodes *port.Cells, attrs *port.Cells, regions *port.Cells, text *port.Cells, raw *port.Cells, tmp *port.Cells) int32 {
	// The caption of table k as the table's first child: `label` (the keyword and the number), the rest as its text.
	var b int32 = k * tbs
	var qn int32 = port.CellsAt(tb, b+15)
	var qf int32 = port.CellsAt(tb, b+14)
	if qn == 0 {
		return 0
	}
	var capn int32 = model.NodeNew(nodes, model.NkCaption(), t)
	var l0 int32 = port.CellsAt(tq, qf)
	var w0 int32 = evidence.LnGet(ln, l0, evidence.LhFirst())
	var s int32 = port.CellsLen(text)
	var x0 int32 = 2000000000
	var y0 int32 = 2000000000
	var x1 int32 = -2000000000
	var y1 int32 = -2000000000
	var q int32 = 0
	var gi int32 = 0
	var j int32 = 0
	var started int32 = 0
	model.NodeSetConf(nodes, capn, 600)
	model.NodeAddSrc(nodes, capn, model.SrText())
	model.NodeAddSrc(nodes, capn, model.SrInfer())
	tbPutWord(text, wd, et, w0)
	model.TextAppendCp(text, 32)
	tbPutWord(text, wd, et, w0+1)
	model.NodeSetAttrText(nodes, attrs, capn, model.FkLabel(), s, port.CellsLen(text)-s)
	port.CellsDrop(raw, 0)
	for q < qn {
		var l int32 = port.CellsAt(tq, qf+q)
		var lf int32 = evidence.LnGet(ln, l, evidence.LhFirst())
		var lc int32 = evidence.LnGet(ln, l, evidence.LhCount())
		if evidence.LnGet(ln, l, evidence.LhX0()) < x0 {
			x0 = evidence.LnGet(ln, l, evidence.LhX0())
		}
		if evidence.LnGet(ln, l, evidence.LhY0()) < y0 {
			y0 = evidence.LnGet(ln, l, evidence.LhY0())
		}
		if evidence.LnGet(ln, l, evidence.LhX1()) > x1 {
			x1 = evidence.LnGet(ln, l, evidence.LhX1())
		}
		if evidence.LnGet(ln, l, evidence.LhY1()) > y1 {
			y1 = evidence.LnGet(ln, l, evidence.LhY1())
		}
		j = 0
		for j < lc {
			var w int32 = lf + j
			var ts int32 = evidence.WdGet(wd, w, evidence.HdTstart())
			var tl int32 = evidence.WdGet(wd, w, evidence.HdTlen())
			if (gi >= 2) && (tl > 0) {
				if !((started == 0) && tbSeparator(wd, et, w)) {
					if started == 1 {
						port.CellsPush(raw, 32)
					}
					started = 1
					var m int32 = 0
					for m < tl {
						port.CellsPush(raw, port.CellsAt(et, ts+m))
						m += 1
					}
				}
			}
			gi += 1
			j += 1
		}
		q += 1
	}
	var t0 int32 = port.CellsLen(text)
	normalize.NzNfc(raw, 0, port.CellsLen(raw), text, tmp, normalize.NzFlagLigatures()+normalize.NzFlagRadicals())
	model.NodeSetText(nodes, capn, t0, port.CellsLen(text)-t0)
	model.NodeAddRegion(nodes, regions, capn, port.CellsAt(tb, b), x0, y0, x1, y1)
	return capn
}

func TbCount(tb *port.Cells) int32 {
	return tbRowsOf(tb, tbs)
}

func TbPage(tb *port.Cells, k int32) int32 {
	return port.CellsAt(tb, k*tbs)
}

func TbTop(tb *port.Cells, k int32) int32 {
	return port.CellsAt(tb, (k*tbs)+2)
}

func TbDue(tb *port.Cells, k int32, page int32, ymid2 int32) bool {
	// Is table k on this page, and its top at or above twice-the-y `ymid2` (a line's baseline sum).
	if k >= tbRowsOf(tb, tbs) {
		return 0 == 1
	}
	if port.CellsAt(tb, k*tbs) != page {
		return 0 == 1
	}
	return (2 * port.CellsAt(tb, (k*tbs)+2)) <= ymid2
}

func TbSkip(tb *port.Cells, k int32, page int32) int32 {
	// The first table at or after k that is on a page at or after `page`.
	var i int32 = k
	for (i < tbRowsOf(tb, tbs)) && (port.CellsAt(tb, i*tbs) < page) {
		i += 1
	}
	return i
}

func tbEmitDropped(tb *port.Cells, f int32, r int32, wd *port.Cells, et *port.Cells, tc *port.Cells, tw *port.Cells, text *port.Cells, raw *port.Cells, tmp *port.Cells, ledger *port.Cells) int32 {
	// A header row of fragment f that repeats the first fragment's (P5.4): into the ledger as `duplicate-header-row`,
	// its box, and its cells' text joined by a space.
	var b int32 = f * tbs
	var cfirst int32 = port.CellsAt(tb, b+9)
	var cend int32 = cfirst + port.CellsAt(tb, b+10)
	var c int32 = cfirst
	var x0 int32 = 2000000000
	var y0 int32 = 2000000000
	var x1 int32 = -2000000000
	var y1 int32 = -2000000000
	var any int32 = 0
	var s int32 = port.CellsLen(text)
	for c < cend {
		if port.CellsAt(tc, c*tcs) == r {
			if port.CellsAt(tc, (c*tcs)+4) < x0 {
				x0 = port.CellsAt(tc, (c*tcs)+4)
			}
			if port.CellsAt(tc, (c*tcs)+5) < y0 {
				y0 = port.CellsAt(tc, (c*tcs)+5)
			}
			if port.CellsAt(tc, (c*tcs)+6) > x1 {
				x1 = port.CellsAt(tc, (c*tcs)+6)
			}
			if port.CellsAt(tc, (c*tcs)+7) > y1 {
				y1 = port.CellsAt(tc, (c*tcs)+7)
			}
			if port.CellsAt(tc, (c*tcs)+9) > 0 {
				if any == 1 {
					model.TextAppendCp(text, 32)
				}
				any = 1
				tbWordsRaw(wd, et, tw, port.CellsAt(tc, (c*tcs)+8), port.CellsAt(tc, (c*tcs)+9), raw)
				normalize.NzNfc(raw, 0, port.CellsLen(raw), text, tmp, normalize.NzFlagLigatures()+normalize.NzFlagRadicals())
			}
		}
		c += 1
	}
	var l int32 = model.LedgerAdd(ledger, model.DrDuplicateHeaderRow(), port.CellsAt(tb, b), x0, y0, x1, y1, 700, model.SrText()+model.SrInfer())
	model.LedgerSetText(ledger, l, s, port.CellsLen(text)-s)
	return 0
}

func TbEmit(tb *port.Cells, k int32, parent int32, wd *port.Cells, et *port.Cells, ln *port.Cells, tc *port.Cells, tw *port.Cells, tq *port.Cells, nodes *port.Cells, attrs *port.Cells, regions *port.Cells, text *port.Cells, raw *port.Cells, tmp *port.Cells, ledger *port.Cells) int32 {
	// Append table k to the Model under `parent` (the root, or the open section, D178): the table node, its caption, its row groups, rows
	// and cells, in document order; the fragments that follow it on later pages (`tb-link`) are its rows too, and
	// their repeated header rows go to the ledger. A table that is a later fragment of another is not written
	// (answers -1). Answers the table's node.
	if port.CellsAt(tb, (k*tbs)+21) != 0 {
		return -1
	}
	var b int32 = k * tbs
	var prof int32 = port.CellsAt(tb, b+5)
	var nhead int32 = port.CellsAt(tb, b+11)
	var t int32 = model.NodeNew(nodes, model.NkTable(), parent)
	var f int32 = k
	var g int32 = -1
	var role int32 = 0
	var row int32 = -1
	var r int32 = 0
	var ci int32 = 0
	var want int32 = 0
	model.NodeSetConf(nodes, t, 600)
	model.NodeAddSrc(nodes, t, model.SrText())
	model.NodeAddSrc(nodes, t, model.SrInfer())
	if prof == pfRuled {
		model.NodeAddSrc(nodes, t, model.SrVector())
	}
	var s int32 = port.CellsLen(text)
	tbPutProfile(text, prof)
	model.NodeSetAttrText(nodes, attrs, t, model.FkProfile(), s, port.CellsLen(text)-s)
	model.NodeSetAttrInt(nodes, attrs, t, model.FkColumns(), port.CellsAt(tb, b+8))
	if port.CellsAt(tb, b+18) > 1 {
		model.NodeSetAttrInt(nodes, attrs, t, model.FkContinued(), port.CellsAt(tb, b+18))
	}
	tbEmitCaption(tb, k, wd, et, ln, tq, t, nodes, attrs, regions, text, raw, tmp)
	for f >= 0 {
		var fb int32 = f * tbs
		var nrows int32 = port.CellsAt(tb, fb+7)
		var cfirst int32 = port.CellsAt(tb, fb+9)
		var cend int32 = cfirst + port.CellsAt(tb, fb+10)
		var nfoot int32 = port.CellsAt(tb, fb+12)
		var nxt int32 = port.CellsAt(tb, fb+19)
		var skip int32 = port.CellsAt(tb, fb+20)
		model.NodeAddRegion(nodes, regions, t, port.CellsAt(tb, fb), port.CellsAt(tb, fb+1), port.CellsAt(tb, fb+2), port.CellsAt(tb, fb+3), port.CellsAt(tb, fb+4))
		r = 0
		for r < skip {
			tbEmitDropped(tb, f, r, wd, et, tc, tw, text, raw, tmp, ledger)
			r += 1
		}
		ci = cfirst
		for (ci < cend) && (port.CellsAt(tc, ci*tcs) < skip) {
			ci += 1
		}
		for r < nrows {
			want = model.RlBody()
			if (f == k) && (r < nhead) {
				want = model.RlHead()
			}
			if (nxt == 0) && (r >= (nrows - nfoot)) {
				want = model.RlFoot()
			}
			if want != role {
				g = model.NodeNew(nodes, model.NkRowgroup(), t)
				model.NodeSetSub(nodes, g, want)
				model.NodeSetConf(nodes, g, 600)
				model.NodeAddSrc(nodes, g, model.SrInfer())
				role = want
			}
			row = model.NodeNew(nodes, model.NkRow(), g)
			model.NodeSetConf(nodes, row, 600)
			model.NodeAddSrc(nodes, row, model.SrInfer())
			for (ci < cend) && (port.CellsAt(tc, ci*tcs) == r) {
				if (port.CellsAt(tc, (ci*tcs)+12) & 1) == 0 {
					tbEmitCell(tb, f, ci, row, wd, et, tc, tw, nodes, attrs, regions, text, raw, tmp)
				}
				ci += 1
			}
			r += 1
		}
		f = nxt - 1
	}
	return t
}

func tbUpright(wd *port.Cells, w int32) bool {
	var r int32 = evidence.WdGet(wd, w, evidence.HdRot())
	return (r < 100) || (r > 35900)
}

func tbWless(wd *port.Cells, a int32, b int32, mode int32) bool {
	// Does word a come before word b: mode 0 by baseline then x, mode 1 by x; then by index.
	if mode == 0 {
		var ya int32 = evidence.WdGet(wd, a, evidence.HdBy1())
		var yb int32 = evidence.WdGet(wd, b, evidence.HdBy1())
		if ya != yb {
			return ya < yb
		}
	}
	var xa int32 = evidence.WdGet(wd, a, evidence.HdX0())
	var xb int32 = evidence.WdGet(wd, b, evidence.HdX0())
	if xa != xb {
		return xa < xb
	}
	return a < b
}

func tbSortWords(wl *port.Cells, wd *port.Cells, from int32, to int32, mode int32) int32 {
	// Shell sort of wl[from, to) by `tb-wless`.
	var n int32 = to - from
	var h int32 = 1
	var i int32 = 0
	var j int32 = 0
	var v int32 = 0
	var u int32 = 0
	var more int32 = 1
	for h < (n / 3) {
		h = (h * 3) + 1
	}
	for h >= 1 {
		i = h
		for i < n {
			v = port.CellsAt(wl, from+i)
			j = i
			more = 1
			for (j >= h) && (more == 1) {
				u = port.CellsAt(wl, from+(j-h))
				if tbWless(wd, v, u, mode) {
					port.CellsSet(wl, from+j, u)
					j -= h
				} else {
					more = 0
				}
			}
			port.CellsSet(wl, from+j, v)
			i += 1
		}
		h = (h - 1) / 3
	}
	return 0
}

func tbRows(wd *port.Cells, w0 int32, w1 int32, rx0 int32, ry0 int32, rx1 int32, ry1 int32, wl *port.Cells, rw *port.Cells, sg *port.Cells) int32 {
	// The upright words w0..w1 of the page whose centre is in the box, as baseline rows and chunks (see the
	// head of this section). Answers the number of rows.
	var w int32 = w0
	var i int32 = 0
	var j int32 = 0
	var n int32 = 0
	port.CellsDrop(wl, 0)
	port.CellsDrop(rw, 0)
	port.CellsDrop(sg, 0)
	for w < w1 {
		var cx int32 = (evidence.WdGet(wd, w, evidence.HdX0()) + evidence.WdGet(wd, w, evidence.HdX1())) / 2
		var cy int32 = (evidence.WdGet(wd, w, evidence.HdY0()) + evidence.WdGet(wd, w, evidence.HdY1())) / 2
		if (evidence.WdGet(wd, w, evidence.HdTlen()) > 0) && tbUpright(wd, w) {
			if (cx >= rx0) && ((cx <= rx1) && ((cy >= ry0) && (cy <= ry1))) {
				port.CellsPush(wl, w)
			}
		}
		w += 1
	}
	n = port.CellsLen(wl)
	tbSortWords(wl, wd, 0, n, 0)
	i = 0
	for i < n {
		var w0i int32 = port.CellsAt(wl, i)
		var ref int32 = evidence.WdGet(wd, w0i, evidence.HdBy1())
		var tol int32 = (3 * tbMax(500, evidence.WdGet(wd, w0i, evidence.WfSize()))) / 10
		j = i + 1
		for (j < n) && (tbAbs(evidence.WdGet(wd, port.CellsAt(wl, j), evidence.HdBy1())-ref) <= tol) {
			j += 1
		}
		tbSortWords(wl, wd, i, j, 1)
		var ri int32 = tbRowsOf(rw, rws)
		var sumy int32 = 0
		var sums int32 = 0
		var x0 int32 = 2000000000
		var x1 int32 = -2000000000
		var y0 int32 = 2000000000
		var y1 int32 = -2000000000
		var k int32 = i
		for k < j {
			var wk int32 = port.CellsAt(wl, k)
			sumy += evidence.WdGet(wd, wk, evidence.HdBy1())
			sums += tbMax(1, evidence.WdGet(wd, wk, evidence.WfSize()))
			if evidence.WdGet(wd, wk, evidence.HdX0()) < x0 {
				x0 = evidence.WdGet(wd, wk, evidence.HdX0())
			}
			if evidence.WdGet(wd, wk, evidence.HdX1()) > x1 {
				x1 = evidence.WdGet(wd, wk, evidence.HdX1())
			}
			if evidence.WdGet(wd, wk, evidence.HdY0()) < y0 {
				y0 = evidence.WdGet(wd, wk, evidence.HdY0())
			}
			if evidence.WdGet(wd, wk, evidence.HdY1()) > y1 {
				y1 = evidence.WdGet(wd, wk, evidence.HdY1())
			}
			k += 1
		}
		var cnt int32 = j - i
		var size int32 = sums / cnt
		var thr int32 = (size * segNum) / segDen
		var sf int32 = tbRowsOf(sg, sgs)
		var cstart int32 = i
		var cmax int32 = evidence.WdGet(wd, port.CellsAt(wl, i), evidence.HdX1())
		port.CellsPush(rw, i)
		port.CellsPush(rw, cnt)
		port.CellsPush(rw, sumy/cnt)
		port.CellsPush(rw, size)
		port.CellsPush(rw, x0)
		port.CellsPush(rw, x1)
		port.CellsPush(rw, y0)
		port.CellsPush(rw, y1)
		port.CellsPush(rw, sf)
		port.CellsPush(rw, 0)
		k = i + 1
		for k <= j {
			if (k == j) || ((evidence.WdGet(wd, port.CellsAt(wl, k), evidence.HdX0()) - cmax) > thr) {
				port.CellsPush(sg, ri)
				port.CellsPush(sg, evidence.WdGet(wd, port.CellsAt(wl, cstart), evidence.HdX0()))
				port.CellsPush(sg, cmax)
				port.CellsPush(sg, cstart)
				port.CellsPush(sg, k-cstart)
				port.CellsPush(sg, 0)
				if k < j {
					cstart = k
					cmax = evidence.WdGet(wd, port.CellsAt(wl, k), evidence.HdX1())
				}
			}
			if k < j {
				if evidence.WdGet(wd, port.CellsAt(wl, k), evidence.HdX1()) > cmax {
					cmax = evidence.WdGet(wd, port.CellsAt(wl, k), evidence.HdX1())
				}
			}
			k += 1
		}
		port.CellsSet(rw, (ri*rws)+9, tbRowsOf(sg, sgs)-sf)
		i = j
	}
	return tbRowsOf(rw, rws)
}

func tbChannels(wd *port.Cells, wl *port.Cells, rw *port.Cells, sg *port.Cells, ra int32, rb int32, allow int32, minw int32, ch *port.Cells, st *port.Cells, en *port.Cells) int32 {
	// The channels of rows ra..rb: the stretches of the x axis, at least minw wide, that at most `allow` of the
	// tabular rows' words (rows of two chunks or more) cover. `st` and `en` are scratch. Answers how many.
	var r int32 = ra
	var k int32 = 0
	var i int32 = 0
	var j int32 = 0
	var cov int32 = 0
	var prev int32 = 0
	var cs int32 = -1
	var ce int32 = 0
	port.CellsDrop(ch, 0)
	port.CellsDrop(st, 0)
	port.CellsDrop(en, 0)
	for r < rb {
		if port.CellsAt(rw, (r*rws)+9) >= 2 {
			k = 0
			for k < port.CellsAt(rw, (r*rws)+1) {
				var w int32 = port.CellsAt(wl, port.CellsAt(rw, r*rws)+k)
				port.CellsPush(st, evidence.WdGet(wd, w, evidence.HdX0()))
				port.CellsPush(en, evidence.WdGet(wd, w, evidence.HdX1()))
				k += 1
			}
		}
		r += 1
	}
	tbSortNums(st)
	tbSortNums(en)
	var n int32 = port.CellsLen(st)
	if n == 0 {
		return 0
	}
	prev = port.CellsAt(st, 0)
	for (i < n) || (j < n) {
		var x int32 = 0
		if i < n {
			x = port.CellsAt(st, i)
		} else {
			x = port.CellsAt(en, j)
		}
		if (j < n) && (port.CellsAt(en, j) < x) {
			x = port.CellsAt(en, j)
		}
		if cov <= allow {
			if cs < 0 {
				cs = prev
			}
			ce = x
		} else {
			if cs >= 0 {
				if (ce - cs) >= minw {
					port.CellsPush(ch, cs)
					port.CellsPush(ch, ce)
				}
				cs = -1
			}
		}
		for (i < n) && (port.CellsAt(st, i) == x) {
			cov += 1
			i += 1
		}
		for (j < n) && (port.CellsAt(en, j) == x) {
			cov -= 1
			j += 1
		}
		prev = x
	}
	if (cs >= 0) && ((ce - cs) >= minw) {
		port.CellsPush(ch, cs)
		port.CellsPush(ch, ce)
	}
	return port.CellsLen(ch) / 2
}

func tbColOf(ch *port.Cells, x int32) int32 {
	// The column of x: how many channel midpoints are at or before it.
	var n int32 = port.CellsLen(ch) / 2
	var i int32 = 0
	var c int32 = 0
	for i < n {
		if ((port.CellsAt(ch, i*2) + port.CellsAt(ch, (i*2)+1)) / 2) <= x {
			c += 1
		}
		i += 1
	}
	return c
}

func tbWordCx(wd *port.Cells, w int32) int32 {
	return (evidence.WdGet(wd, w, evidence.HdX0()) + evidence.WdGet(wd, w, evidence.HdX1())) / 2
}

func tbChunkA(wd *port.Cells, wl *port.Cells, sg *port.Cells, ch *port.Cells, s int32) int32 {
	// The first column of chunk s: the column of its first word's centre.
	return tbColOf(ch, tbWordCx(wd, port.CellsAt(wl, port.CellsAt(sg, (s*sgs)+3))))
}

func tbChunkB(wd *port.Cells, wl *port.Cells, sg *port.Cells, ch *port.Cells, s int32) int32 {
	// The last column of chunk s: the column of its last word's centre.
	return tbColOf(ch, tbWordCx(wd, port.CellsAt(wl, (port.CellsAt(sg, (s*sgs)+3)+port.CellsAt(sg, (s*sgs)+4))-1)))
}

func tbRowMap(wd *port.Cells, wl *port.Cells, rw *port.Cells, sg *port.Cells, ch *port.Cells, ra int32, rb int32, ncols int32, rmap *port.Cells, occ *port.Cells) int32 {
	// The table row of each baseline row ra..rb (rmap[r - ra]): a baseline row goes on the row above when
	// it is a continuation of a wrapped cell: a tight line pitch (at most 1.35 of the size and 4/5 of the
	// mean pitch), no chunk with a span, and chunks only in columns the row above had, at most half of them.
	// Answers the number of table rows.
	var r int32 = ra
	var rows int32 = -1
	var c int32 = 0
	var cont int32 = 0
	var occn int32 = 0
	var ok int32 = 1
	var s int32 = 0
	var mean int32 = 0
	if (rb - ra) > 1 {
		mean = (port.CellsAt(rw, ((rb-1)*rws)+2) - port.CellsAt(rw, (ra*rws)+2)) / ((rb - ra) - 1)
	}
	port.CellsDrop(rmap, 0)
	port.CellsDrop(occ, 0)
	for c < ncols {
		port.CellsPush(occ, 0)
		c += 1
	}
	for r < rb {
		cont = 0
		if (rows > -1) && (r > ra) {
			var pitch int32 = port.CellsAt(rw, (r*rws)+2) - port.CellsAt(rw, ((r-1)*rws)+2)
			var size int32 = port.CellsAt(rw, (r*rws)+3)
			var nchunks int32 = port.CellsAt(rw, (r*rws)+9)
			if ((pitch * 20) <= (size * 27)) && ((mean > 0) && ((pitch * 5) <= (mean * 4))) {
				occn = 0
				c = 0
				for c < ncols {
					if port.CellsAt(occ, c) == 1 {
						occn += 1
					}
					c += 1
				}
				if (nchunks < occn) && ((nchunks * 2) <= occn) {
					ok = 1
					s = 0
					for s < nchunks {
						var si int32 = port.CellsAt(rw, (r*rws)+8) + s
						var a int32 = tbChunkA(wd, wl, sg, ch, si)
						var b int32 = tbChunkB(wd, wl, sg, ch, si)
						if a != b {
							ok = 0
						}
						if port.CellsAt(occ, a) != 1 {
							ok = 0
						}
						s += 1
					}
					cont = ok
				}
			}
		}
		if cont == 0 {
			rows += 1
			c = 0
			for c < ncols {
				port.CellsSet(occ, c, 0)
				c += 1
			}
		}
		s = 0
		for s < port.CellsAt(rw, (r*rws)+9) {
			var si int32 = port.CellsAt(rw, (r*rws)+8) + s
			var a int32 = tbChunkA(wd, wl, sg, ch, si)
			var b int32 = tbChunkB(wd, wl, sg, ch, si)
			c = a
			for c <= b {
				port.CellsSet(occ, c, 1)
				c += 1
			}
			s += 1
		}
		port.CellsPush(rmap, rows)
		r += 1
	}
	return rows + 1
}

func tbCut(ch *port.Cells, k int32, lo int32, hi int32) int32 {
	// The boundary before column k: lo for the first, else the midpoint of channel k-1; hi after the last.
	var n int32 = port.CellsLen(ch) / 2
	if k <= 0 {
		return lo
	}
	if k > n {
		return hi
	}
	return (port.CellsAt(ch, (k-1)*2) + port.CellsAt(ch, ((k-1)*2)+1)) / 2
}

func tbTextGrid(wd *port.Cells, wl *port.Cells, rw *port.Cells, sg *port.Cells, ch *port.Cells, st *port.Cells, en *port.Cells, rmap *port.Cells, gm *port.Cells, gs *port.Cells, ry *port.Cells, pr *port.Cells, so *port.Cells, tb *port.Cells, tc *port.Cells, tw *port.Cells, tx *port.Cells, page int32, ra int32, rb int32, profile int32, score int32, ext int32, bx0 int32, by0 int32, bx1 int32, by1 int32) int32 {
	// The cells of the rows ra..rb (see the head of this section) as a candidate table of this profile:
	// ext 1 means `rmap` already says which table row each baseline row is (shaded: the fills' bands). The box
	// bx0..by1 widens the box of the words (the rules, the fills): 2000000000 2000000000 -2000000000 -2000000000
	// for none. Answers the
	// table's index, -1 when there are not two columns and two rows.
	var ntab int32 = 0
	var sumsz int32 = 0
	var r int32 = ra
	var nch int32 = 0
	var ncols int32 = 0
	var nrows int32 = 0
	var c int32 = 0
	var s int32 = 0
	var q int32 = 0
	var a int32 = 0
	var b int32 = 0
	var tr int32 = 0
	var minx int32 = 2000000000
	var maxx int32 = -2000000000
	var miny int32 = 2000000000
	var maxy int32 = -2000000000
	for r < rb {
		if port.CellsAt(rw, (r*rws)+9) >= 2 {
			ntab += 1
		}
		sumsz += port.CellsAt(rw, (r*rws)+3)
		if port.CellsAt(rw, (r*rws)+4) < minx {
			minx = port.CellsAt(rw, (r*rws)+4)
		}
		if port.CellsAt(rw, (r*rws)+5) > maxx {
			maxx = port.CellsAt(rw, (r*rws)+5)
		}
		if port.CellsAt(rw, (r*rws)+6) < miny {
			miny = port.CellsAt(rw, (r*rws)+6)
		}
		if port.CellsAt(rw, (r*rws)+7) > maxy {
			maxy = port.CellsAt(rw, (r*rws)+7)
		}
		r += 1
	}
	if (ntab < 2) || ((rb - ra) <= 1) {
		return -1
	}
	nch = tbChannels(wd, wl, rw, sg, ra, rb, ntab/6, ((sumsz/(rb-ra))*segNum)/segDen, ch, st, en)
	if nch < 1 {
		return -1
	}
	ncols = nch + 1
	if ncols > 40 {
		return -1
	}
	if ext == 0 {
		nrows = tbRowMap(wd, wl, rw, sg, ch, ra, rb, ncols, rmap, st)
	} else {
		nrows = 0
		r = 0
		for r < (rb - ra) {
			if port.CellsAt(rmap, r) >= nrows {
				nrows = port.CellsAt(rmap, r) + 1
			}
			r += 1
		}
	}
	if nrows < 2 {
		return -1
	}
	port.CellsDrop(gm, 0)
	port.CellsDrop(gs, 0)
	port.CellsDrop(en, 0)
	port.CellsDrop(ry, 0)
	c = 0
	for c < (nrows * ncols) {
		port.CellsPush(gm, -1)
		port.CellsPush(gs, 0)
		port.CellsPush(en, -1)
		c += 1
	}
	c = 0
	for c < nrows {
		port.CellsPush(ry, 2000000000)
		port.CellsPush(ry, -2000000000)
		c += 1
	}
	r = ra
	for r < rb {
		tr = port.CellsAt(rmap, r-ra)
		if tr >= 0 {
			if port.CellsAt(rw, (r*rws)+6) < port.CellsAt(ry, tr*2) {
				port.CellsSet(ry, tr*2, port.CellsAt(rw, (r*rws)+6))
			}
			if port.CellsAt(rw, (r*rws)+7) > port.CellsAt(ry, (tr*2)+1) {
				port.CellsSet(ry, (tr*2)+1, port.CellsAt(rw, (r*rws)+7))
			}
			s = 0
			for s < port.CellsAt(rw, (r*rws)+9) {
				q = port.CellsAt(rw, (r*rws)+8) + s
				a = tbChunkA(wd, wl, sg, ch, q)
				b = tbChunkB(wd, wl, sg, ch, q)
				if port.CellsAt(gm, (tr*ncols)+a) == -1 {
					var free int32 = 1
					var kf int32 = a
					for kf <= b {
						if port.CellsAt(gm, (tr*ncols)+kf) != -1 {
							free = 0
						}
						kf += 1
					}
					if free == 0 {
						b = a
					}
					kf = a
					for kf <= b {
						port.CellsSet(gm, (tr*ncols)+kf, a)
						kf += 1
					}
					port.CellsSet(gs, (tr*ncols)+a, (b-a)+1)
				}
				s += 1
			}
		}
		r += 1
	}
	var cfirst int32 = tbRowsOf(tc, tcs)
	tr = 0
	for tr < nrows {
		c = 0
		for c < ncols {
			var st0 int32 = port.CellsAt(gm, (tr*ncols)+c)
			var span int32 = 1
			if st0 >= 0 {
				span = port.CellsAt(gs, (tr*ncols)+st0)
			}
			if (st0 < 0) || (st0 == c) {
				var idx int32 = tbCellAdd(tc, tr, c, 1, span, tbCut(ch, c, minx, maxx), port.CellsAt(ry, tr*2), tbCut(ch, c+span, minx, maxx), port.CellsAt(ry, (tr*2)+1))
				var ki int32 = c
				for ki < (c + span) {
					port.CellsSet(en, (tr*ncols)+ki, idx)
					ki += 1
				}
			}
			c += span
		}
		tr += 1
	}
	port.CellsDrop(pr, 0)
	r = ra
	for r < rb {
		tr = port.CellsAt(rmap, r-ra)
		if tr >= 0 {
			s = 0
			for s < port.CellsAt(rw, (r*rws)+9) {
				q = port.CellsAt(rw, (r*rws)+8) + s
				a = tbChunkA(wd, wl, sg, ch, q)
				var cell int32 = port.CellsAt(en, (tr*ncols)+a)
				var kw int32 = port.CellsAt(sg, (q*sgs)+3)
				for kw < (port.CellsAt(sg, (q*sgs)+3) + port.CellsAt(sg, (q*sgs)+4)) {
					tbPairAdd(pr, wd, cell, port.CellsAt(wl, kw))
					kw += 1
				}
				s += 1
			}
		}
		r += 1
	}
	tbFlushPairs(pr, so, wd, tc, tw)
	var x0 int32 = minx
	var y0 int32 = miny
	var x1 int32 = maxx
	var y1 int32 = maxy
	if bx0 < x0 {
		x0 = bx0
	}
	if by0 < y0 {
		y0 = by0
	}
	if bx1 > x1 {
		x1 = bx1
	}
	if by1 > y1 {
		y1 = by1
	}
	var t int32 = tbAdd(tb, page, x0, y0, x1, y1, profile, score, nrows, ncols, cfirst, tbRowsOf(tc, tcs)-cfirst)
	var k int32 = 0
	port.CellsSet(tb, (t*tbs)+16, port.CellsLen(tx))
	port.CellsSet(tb, (t*tbs)+17, ncols+1)
	for k <= ncols {
		port.CellsPush(tx, tbCut(ch, k, minx, maxx))
		k += 1
	}
	return t
}

func tbNumChar(cp int32) bool {
	// A character a number may hold besides digits: separators, signs, currency, percent, brackets.
	return (cp == 44) || ((cp == 46) || ((cp == 45) || ((cp == 43) || ((cp == 37) || ((cp == 36) || ((cp == 8364) || ((cp == 163) || ((cp == 165) || ((cp == 40) || ((cp == 41) || ((cp == 47) || ((cp == 58) || ((cp == 8722) || ((cp == 8211) || ((cp == 160) || ((cp == 8201) || (cp == 8239)))))))))))))))))
}

func tbCellNumeric(wd *port.Cells, et *port.Cells, tw *port.Cells, tc *port.Cells, c int32) int32 {
	// 1 when the cell is up to three words made only of digits and number marks, with a digit; else 0.
	var cb int32 = c * tcs
	var n int32 = port.CellsAt(tc, cb+9)
	var from int32 = port.CellsAt(tc, cb+8)
	var digits int32 = 0
	var k int32 = 0
	var j int32 = 0
	if (n == 0) || (n > 3) {
		return 0
	}
	for k < n {
		var w int32 = port.CellsAt(tw, from+k)
		var ts int32 = evidence.WdGet(wd, w, evidence.HdTstart())
		var tl int32 = evidence.WdGet(wd, w, evidence.HdTlen())
		j = 0
		for j < tl {
			var cp int32 = port.CellsAt(et, ts+j)
			if (cp >= 48) && (cp <= 57) {
				digits += 1
			} else if !tbNumChar(cp) {
				return 0
			}
			j += 1
		}
		k += 1
	}
	if digits > 0 {
		return 1
	}
	return 0
}

func tbCellBold(wd *port.Cells, tw *port.Cells, tc *port.Cells, c int32) int32 {
	// 1 when every word of the cell is bold, 0 when one is not, -1 for an empty cell.
	var cb int32 = c * tcs
	var n int32 = port.CellsAt(tc, cb+9)
	var from int32 = port.CellsAt(tc, cb+8)
	var k int32 = 0
	if n == 0 {
		return -1
	}
	for k < n {
		if (evidence.WdGet(wd, port.CellsAt(tw, from+k), evidence.WfStyle()) & model.SyBold()) == 0 {
			return 0
		}
		k += 1
	}
	return 1
}

func tbRowStat(tc *port.Cells, cfirst int32, cend int32, r int32, wd *port.Cells, et *port.Cells, tw *port.Cells, what int32) int32 {
	// Of the cells that start in row r: what 0 how many are not empty, 1 how many are bold, 2 how many are
	// numeric, 3 how many there are.
	var c int32 = cfirst
	var n int32 = 0
	for c < cend {
		if port.CellsAt(tc, c*tcs) == r {
			if what == 3 {
				n += 1
			}
			if (what == 0) && (port.CellsAt(tc, (c*tcs)+9) > 0) {
				n += 1
			}
			if (what == 1) && (tbCellBold(wd, tw, tc, c) == 1) {
				n += 1
			}
			if (what == 2) && (tbCellNumeric(wd, et, tw, tc, c) == 1) {
				n += 1
			}
		}
		c += 1
	}
	return n
}

func tbRowBold(tc *port.Cells, cfirst int32, cend int32, r int32, wd *port.Cells, et *port.Cells, tw *port.Cells) bool {
	// Is row r bold: it has cells and every one that is not empty is bold.
	var ne int32 = tbRowStat(tc, cfirst, cend, r, wd, et, tw, 0)
	return (ne > 0) && (tbRowStat(tc, cfirst, cend, r, wd, et, tw, 1) == ne)
}

func tbNumCols(tb *port.Cells, k int32, r0 int32, wd *port.Cells, et *port.Cells, tc *port.Cells, tw *port.Cells) int32 {
	// How many columns, over the rows from r0 on, have at least 3 cells of which 4/5 are numeric.
	var b int32 = k * tbs
	var ncols int32 = port.CellsAt(tb, b+8)
	var cfirst int32 = port.CellsAt(tb, b+9)
	var cend int32 = cfirst + port.CellsAt(tb, b+10)
	var col int32 = 0
	var c int32 = 0
	var ne int32 = 0
	var nn int32 = 0
	var total int32 = 0
	for col < ncols {
		ne = 0
		nn = 0
		c = cfirst
		for c < cend {
			if (port.CellsAt(tc, (c*tcs)+1) == col) && ((port.CellsAt(tc, c*tcs) >= r0) && (port.CellsAt(tc, (c*tcs)+3) == 1)) {
				if port.CellsAt(tc, (c*tcs)+9) > 0 {
					ne += 1
					if tbCellNumeric(wd, et, tw, tc, c) == 1 {
						nn += 1
					}
				}
			}
			c += 1
		}
		if (ne >= 3) && ((nn * 10) >= (ne * 8)) {
			total += 1
		}
		col += 1
	}
	return total
}

func tbHeadRows(tb *port.Cells, k int32, wd *port.Cells, et *port.Cells, tc *port.Cells, tw *port.Cells) int32 {
	// How many leading rows are the header: the bold ones (a table of bold rows has none, and a header is
	// at most half of the rows); else, when the first row has no number and a column below it is numeric,
	// that one row.
	var b int32 = k * tbs
	var nrows int32 = port.CellsAt(tb, b+7)
	var cfirst int32 = port.CellsAt(tb, b+9)
	var cend int32 = cfirst + port.CellsAt(tb, b+10)
	var h int32 = 0
	for (h < (nrows - 1)) && tbRowBold(tc, cfirst, cend, h, wd, et, tw) {
		h += 1
	}
	if (h > 0) && ((h * 2) <= (nrows + 1)) {
		return h
	}
	if (nrows >= 3) && (tbRowStat(tc, cfirst, cend, 0, wd, et, tw, 2) == 0) {
		if (tbRowStat(tc, cfirst, cend, 0, wd, et, tw, 0) >= 2) && (tbNumCols(tb, k, 1, wd, et, tc, tw) >= 1) {
			return 1
		}
	}
	return 0
}

func tbFootRows(tb *port.Cells, k int32, nhead int32, wd *port.Cells, et *port.Cells, tc *port.Cells, tw *port.Cells) int32 {
	// 1 when the last row is bold and the row above it is not, with at least two body rows; else 0.
	var b int32 = k * tbs
	var nrows int32 = port.CellsAt(tb, b+7)
	var cfirst int32 = port.CellsAt(tb, b+9)
	var cend int32 = cfirst + port.CellsAt(tb, b+10)
	if (nrows - nhead) < 3 {
		return 0
	}
	if tbRowBold(tc, cfirst, cend, nrows-1, wd, et, tw) && !tbRowBold(tc, cfirst, cend, nrows-2, wd, et, tw) {
		return 1
	}
	return 0
}

func tbColAlign(tb *port.Cells, k int32, col int32, r0 int32, r1 int32, wd *port.Cells, tc *port.Cells, tw *port.Cells) int32 {
	// The alignment (an `al` code, 0 none) of the cells of column `col` in rows r0..r1 (single-column ones),
	// decided together against their text extent (SPEC 10.10): start when every start gap is within t (a
	// quarter of the size) and the end gaps vary by more than 2t, end the other way round, center when the
	// two gaps agree within t on every cell and the start gap varies.
	var b int32 = k * tbs
	var cfirst int32 = port.CellsAt(tb, b+9)
	var cend int32 = cfirst + port.CellsAt(tb, b+10)
	var c int32 = cfirst
	var n int32 = 0
	var box0 int32 = 2000000000
	var box1 int32 = -2000000000
	var size int32 = 0
	var smax int32 = -2000000000
	var smin int32 = 2000000000
	var emax int32 = -2000000000
	var emin int32 = 2000000000
	var cen int32 = 1
	var res int32 = 0
	for c < cend {
		if (port.CellsAt(tc, (c*tcs)+1) == col) && ((port.CellsAt(tc, c*tcs) >= r0) && ((port.CellsAt(tc, c*tcs) < r1) && ((port.CellsAt(tc, (c*tcs)+3) == 1) && (port.CellsAt(tc, (c*tcs)+9) > 0)))) {
			n += 1
			if port.CellsAt(tc, (c*tcs)+13) < box0 {
				box0 = port.CellsAt(tc, (c*tcs)+13)
			}
			if port.CellsAt(tc, (c*tcs)+14) > box1 {
				box1 = port.CellsAt(tc, (c*tcs)+14)
			}
			if size == 0 {
				size = evidence.WdGet(wd, port.CellsAt(tw, port.CellsAt(tc, (c*tcs)+8)), evidence.WfSize())
			}
		}
		c += 1
	}
	if n < 2 {
		return 0
	}
	var t int32 = size / 4
	c = cfirst
	for c < cend {
		if (port.CellsAt(tc, (c*tcs)+1) == col) && ((port.CellsAt(tc, c*tcs) >= r0) && ((port.CellsAt(tc, c*tcs) < r1) && ((port.CellsAt(tc, (c*tcs)+3) == 1) && (port.CellsAt(tc, (c*tcs)+9) > 0)))) {
			var sg0 int32 = port.CellsAt(tc, (c*tcs)+13) - box0
			var eg0 int32 = box1 - port.CellsAt(tc, (c*tcs)+14)
			if sg0 > smax {
				smax = sg0
			}
			if sg0 < smin {
				smin = sg0
			}
			if eg0 > emax {
				emax = eg0
			}
			if eg0 < emin {
				emin = eg0
			}
			if tbAbs(sg0-eg0) > t {
				cen = 0
			}
		}
		c += 1
	}
	if (smax <= t) && ((emax - emin) > (2 * t)) {
		res = 1
	}
	if (res == 0) && ((emax <= t) && ((smax - smin) > (2 * t))) {
		res = 3
	}
	if (res == 0) && ((cen == 1) && ((smax - smin) > (2 * t))) {
		res = 2
	}
	return res
}

func tbHeadAlign(tb *port.Cells, k int32, c int32, colal int32, wd *port.Cells, tc *port.Cells, tw *port.Cells) int32 {
	// The alignment of header cell c: against its cell box in a ruled table (and when it spans columns),
	// else against the extent of its column's BODY text (the header is not its own measure): centre or end when
	// the text is clear of the body's edges by 4t, start when it is flush and the column's body is start.
	var b int32 = k * tbs
	var cfirst int32 = port.CellsAt(tb, b+9)
	var cend int32 = cfirst + port.CellsAt(tb, b+10)
	var cb int32 = c * tcs
	var col int32 = port.CellsAt(tc, cb+1)
	var bx0 int32 = port.CellsAt(tc, cb+4)
	var bx1 int32 = port.CellsAt(tc, cb+6)
	var j int32 = cfirst
	if port.CellsAt(tc, cb+9) == 0 {
		return 0
	}
	if (port.CellsAt(tb, b+5) != pfRuled) && (port.CellsAt(tc, cb+3) == 1) {
		bx0 = 2000000000
		bx1 = -2000000000
		for j < cend {
			if (port.CellsAt(tc, (j*tcs)+1) == col) && ((port.CellsAt(tc, (j*tcs)+3) == 1) && ((port.CellsAt(tc, j*tcs) >= port.CellsAt(tb, b+11)) && (port.CellsAt(tc, (j*tcs)+9) > 0))) {
				if port.CellsAt(tc, (j*tcs)+13) < bx0 {
					bx0 = port.CellsAt(tc, (j*tcs)+13)
				}
				if port.CellsAt(tc, (j*tcs)+14) > bx1 {
					bx1 = port.CellsAt(tc, (j*tcs)+14)
				}
			}
			j += 1
		}
		if bx0 > bx1 {
			return 0
		}
	}
	var t int32 = evidence.WdGet(wd, port.CellsAt(tw, port.CellsAt(tc, cb+8)), evidence.WfSize()) / 4
	var sg0 int32 = port.CellsAt(tc, cb+13) - bx0
	var eg0 int32 = bx1 - port.CellsAt(tc, cb+14)
	if (tbAbs(sg0-eg0) <= t) && (tbMin(sg0, eg0) >= (4 * t)) {
		return 2
	}
	if (eg0 >= 0) && ((eg0 <= t) && (sg0 >= (4 * t))) {
		return 3
	}
	if (sg0 >= 0) && ((sg0 <= t) && ((colal == 1) && (eg0 >= 0))) {
		return 1
	}
	return 0
}

func tbAligns(tb *port.Cells, k int32, wd *port.Cells, tc *port.Cells, tw *port.Cells) int32 {
	// Set the `align` of every cell of table k: the body columns together, the header cells each, the foot
	// cells as their column.
	var b int32 = k * tbs
	var nrows int32 = port.CellsAt(tb, b+7)
	var ncols int32 = port.CellsAt(tb, b+8)
	var cfirst int32 = port.CellsAt(tb, b+9)
	var cend int32 = cfirst + port.CellsAt(tb, b+10)
	var nhead int32 = port.CellsAt(tb, b+11)
	var nfoot int32 = port.CellsAt(tb, b+12)
	var col int32 = 0
	var c int32 = 0
	var al int32 = 0
	for col < ncols {
		al = tbColAlign(tb, k, col, nhead, nrows-nfoot, wd, tc, tw)
		c = cfirst
		for c < cend {
			if (port.CellsAt(tc, (c*tcs)+1) == col) && (port.CellsAt(tc, (c*tcs)+3) == 1) {
				if port.CellsAt(tc, c*tcs) >= nhead {
					port.CellsSet(tc, (c*tcs)+11, al)
				} else {
					var ha int32 = tbHeadAlign(tb, k, c, al, wd, tc, tw)
					port.CellsSet(tc, (c*tcs)+11, ha)
				}
			}
			c += 1
		}
		col += 1
	}
	c = cfirst
	for c < cend {
		if (port.CellsAt(tc, c*tcs) < nhead) && (port.CellsAt(tc, (c*tcs)+3) > 1) {
			var ha int32 = tbHeadAlign(tb, k, c, 0, wd, tc, tw)
			port.CellsSet(tc, (c*tcs)+11, ha)
		}
		c += 1
	}
	return 0
}

var tbKw [81]int32 = [81]int32{
	5, 116, 97, 98, 108, 101, 0, 0, 0,
	3, 116, 97, 98, 0, 0, 0, 0, 0,
	7, 116, 97, 98, 101, 108, 108, 101, 0,
	7, 116, 97, 98, 108, 101, 97, 117, 0,
	5, 116, 97, 98, 108, 97, 0, 0, 0,
	6, 116, 97, 98, 101, 108, 97, 0, 0,
	7, 116, 97, 98, 101, 108, 108, 97, 0,
	5, 116, 97, 98, 101, 108, 0, 0, 0,
	6, 116, 97, 98, 101, 108, 108, 0, 0,
}

func tbLower(cp int32) int32 {
	if (cp >= 65) && (cp <= 90) {
		return cp + 32
	}
	return cp
}

func tbIsLabelWord(wd *port.Cells, et *port.Cells, w int32) bool {
	// Is the word a table keyword (any case, a trailing full stop ignored): Table, Tab., Tabelle, Tableau...
	var ts int32 = evidence.WdGet(wd, w, evidence.HdTstart())
	var tl int32 = evidence.WdGet(wd, w, evidence.HdTlen())
	var r int32 = 0
	var j int32 = 0
	var same int32 = 1
	if tl < 1 {
		return 0 == 1
	}
	if port.CellsAt(et, ts+(tl-1)) == 46 {
		tl -= 1
	}
	for r < 9 {
		if tbKw[r*9+0] == tl {
			same = 1
			j = 0
			for j < tl {
				if tbLower(port.CellsAt(et, ts+j)) != tbKw[r*9+(j+1)] {
					same = 0
				}
				j += 1
			}
			if same == 1 {
				return 1 == 1
			}
		}
		r += 1
	}
	return 0 == 1
}

func tbIsLabelNumber(wd *port.Cells, et *port.Cells, w int32) bool {
	// A table number: starts with a digit, or a capital letter and a digit (S1).
	var ts int32 = evidence.WdGet(wd, w, evidence.HdTstart())
	var tl int32 = evidence.WdGet(wd, w, evidence.HdTlen())
	if tl < 1 {
		return 0 == 1
	}
	var c0 int32 = port.CellsAt(et, ts)
	if (c0 >= 48) && (c0 <= 57) {
		return 1 == 1
	}
	if (tl >= 2) && ((c0 >= 65) && (c0 <= 90)) {
		var c1 int32 = port.CellsAt(et, ts+1)
		return (c1 >= 48) && (c1 <= 57)
	}
	return 0 == 1
}

func tbLineLabel(wd *port.Cells, et *port.Cells, ln *port.Cells, l int32) bool {
	// Does line l start with a table keyword and a table number.
	var w0 int32 = evidence.LnGet(ln, l, evidence.LhFirst())
	if evidence.LnGet(ln, l, evidence.LhCount()) < 2 {
		return 0 == 1
	}
	return tbIsLabelWord(wd, et, w0) && tbIsLabelNumber(wd, et, w0+1)
}

func tbCaption(tb *port.Cells, k int32, wd *port.Cells, et *port.Cells, ln *port.Cells, l0 int32, l1 int32, tq *port.Cells) int32 {
	// Find the caption of table k among the unclaimed lines l0..l1: a line that starts with a table keyword
	// and a number, over the table or under it within two and a half line heights, preferring the one over it;
	// the lines on its baseline to its right and the lines under it that continue it are part of it. They are
	// claimed and their numbers pushed on `tq` (qfirst, qcount in the table's cells 14 and 15).
	var b int32 = k * tbs
	var tx0 int32 = port.CellsAt(tb, b+1)
	var ty0 int32 = port.CellsAt(tb, b+2)
	var tx1 int32 = port.CellsAt(tb, b+3)
	var ty1 int32 = port.CellsAt(tb, b+4)
	var l int32 = l0
	var best int32 = -1
	var bestd int32 = 2000000000
	var above int32 = 0
	for l < l1 {
		if evidence.LnGet(ln, l, 15) == 0 {
			if tbLineLabel(wd, et, ln, l) {
				if (evidence.LnGet(ln, l, evidence.LhX0()) < tx1) && (evidence.LnGet(ln, l, evidence.LhX1()) > tx0) {
					var lht int32 = evidence.LnGet(ln, l, evidence.LhY1()) - evidence.LnGet(ln, l, evidence.LhY0())
					var da int32 = ty0 - evidence.LnGet(ln, l, evidence.LhY1())
					var db int32 = evidence.LnGet(ln, l, evidence.LhY0()) - ty1
					if (da >= -300) && ((da * 2) <= (lht * 5)) {
						if tbAbs(da) < bestd {
							best = l
							bestd = tbAbs(da)
							above = 1
						}
					}
					if (db >= -300) && (((db * 2) <= (lht * 5)) && (above == 0)) {
						if tbAbs(db) < bestd {
							best = l
							bestd = tbAbs(db)
						}
					}
				}
			}
		}
		l += 1
	}
	if best < 0 {
		return 0
	}
	port.CellsSet(tb, b+14, port.CellsLen(tq))
	port.CellsPush(tq, best)
	evidence.LnSet(ln, best, 15, k+1)
	var h int32 = evidence.LnGet(ln, best, evidence.LhY1()) - evidence.LnGet(ln, best, evidence.LhY0())
	var curx1 int32 = evidence.LnGet(ln, best, evidence.LhX1())
	var cury1 int32 = evidence.LnGet(ln, best, evidence.LhY1())
	var more int32 = 1
	var rounds int32 = 0
	var pick int32 = -1
	l = l0
	for l < l1 {
		if evidence.LnGet(ln, l, 15) == 0 {
			if (evidence.LnGet(ln, l, evidence.LhX0()) > (curx1 - 100)) && ((evidence.LnGet(ln, l, evidence.LhX0()) - curx1) <= (2 * h)) {
				if tbAbs(evidence.LnGet(ln, l, evidence.LhBy0())-evidence.LnGet(ln, best, evidence.LhBy0())) <= (h / 3) {
					port.CellsPush(tq, l)
					evidence.LnSet(ln, l, 15, k+1)
					curx1 = evidence.LnGet(ln, l, evidence.LhX1())
				}
			}
		}
		l += 1
	}
	for (more == 1) && (rounds < 6) {
		more = 0
		rounds += 1
		pick = -1
		l = l0
		for l < l1 {
			if evidence.LnGet(ln, l, 15) == 0 {
				if (evidence.LnGet(ln, l, evidence.LhY0()) >= (cury1 - 200)) && ((evidence.LnGet(ln, l, evidence.LhY0()) - cury1) <= ((h * 3) / 5)) {
					if (evidence.LnGet(ln, l, evidence.LhX0()) < tx1) && (evidence.LnGet(ln, l, evidence.LhX1()) > tx0) {
						if !tbLineLabel(wd, et, ln, l) {
							if evidence.LnGet(ln, l, evidence.LhY1()) < (ty0 + 300) {
								if pick < 0 {
									pick = l
								}
							}
						}
					}
				}
			}
			l += 1
		}
		if (pick >= 0) && (above == 1) {
			port.CellsPush(tq, pick)
			evidence.LnSet(ln, pick, 15, k+1)
			cury1 = evidence.LnGet(ln, pick, evidence.LhY1())
			more = 1
		}
	}
	port.CellsSet(tb, b+15, port.CellsLen(tq)-port.CellsAt(tb, b+14))
	return 1
}

func tbReject(tb *port.Cells, tc *port.Cells, tw *port.Cells, tx *port.Cells, nt int32, c0 int32, w0 int32, x0 int32) int32 {
	// Forget the candidate that was just built: every arena goes back to the length it had.
	port.CellsDrop(tb, nt*tbs)
	port.CellsDrop(tc, c0*tcs)
	port.CellsDrop(tw, w0)
	port.CellsDrop(tx, x0)
	return 0
}

func tbTabularRows(tb *port.Cells, k int32, tc *port.Cells) int32 {
	// How many rows of table k have two cells or more with text.
	var b int32 = k * tbs
	var cfirst int32 = port.CellsAt(tb, b+9)
	var cend int32 = cfirst + port.CellsAt(tb, b+10)
	var c int32 = cfirst
	var row int32 = -1
	var cnt int32 = 0
	var total int32 = 0
	for c < cend {
		if port.CellsAt(tc, c*tcs) != row {
			if cnt >= 2 {
				total += 1
			}
			row = port.CellsAt(tc, c*tcs)
			cnt = 0
		}
		if port.CellsAt(tc, (c*tcs)+9) > 0 {
			cnt += 1
		}
		c += 1
	}
	if cnt >= 2 {
		total += 1
	}
	return total
}

func tbScore(tb *port.Cells, k int32, wd *port.Cells, et *port.Cells, tc *port.Cells, tw *port.Cells) int32 {
	// The score (0 to 1000, 0 = not a table) of text-based candidate k of its profile (SPEC 10.5): prose in
	// columns is not a table, so cells that are long, or that end like sentences, refuse it. The whitespace
	// profile has no rules or fills to vouch for it and asks for more: three columns or a numeric column, and a header.
	var b int32 = k * tbs
	var prof int32 = port.CellsAt(tb, b+5)
	var ncols int32 = port.CellsAt(tb, b+8)
	var nrows int32 = port.CellsAt(tb, b+7)
	var cfirst int32 = port.CellsAt(tb, b+9)
	var cend int32 = cfirst + port.CellsAt(tb, b+10)
	var c int32 = cfirst
	var ne int32 = 0
	var nw int32 = 0
	var nlong int32 = 0
	var nend int32 = 0
	var nprose int32 = 0
	var score int32 = 0
	for c < cend {
		var cn int32 = port.CellsAt(tc, (c*tcs)+9)
		if cn > 0 {
			ne += 1
			nw += cn
			if cn > 8 {
				nlong += 1
			}
			if cn >= 2 {
				var fw int32 = port.CellsAt(tw, port.CellsAt(tc, (c*tcs)+8))
				var lw2 int32 = port.CellsAt(tw, port.CellsAt(tc, (c*tcs)+8)+(cn-1))
				var c0 int32 = port.CellsAt(et, evidence.WdGet(wd, fw, evidence.HdTstart()))
				var ts2 int32 = evidence.WdGet(wd, lw2, evidence.HdTstart())
				var tl2 int32 = evidence.WdGet(wd, lw2, evidence.HdTlen())
				if (c0 >= 97) && (c0 <= 122) {
					nprose += 1
				}
				if (tl2 > 1) && (port.CellsAt(et, ts2+(tl2-1)) == 45) {
					nprose += 1
				}
			}
			if cn >= 3 {
				var lw int32 = port.CellsAt(tw, port.CellsAt(tc, (c*tcs)+8)+(cn-1))
				var ts int32 = evidence.WdGet(wd, lw, evidence.HdTstart())
				var tl int32 = evidence.WdGet(wd, lw, evidence.HdTlen())
				if (tl > 0) && (port.CellsAt(et, ts+(tl-1)) == 46) {
					nend += 1
				}
			}
		}
		c += 1
	}
	if ne < 4 {
		return 0
	}
	if (nprose * 10) > (ne * 3) {
		return 0
	}
	if (prof == pfWhitespace) && ((ne * 100) < ((nrows * ncols) * 55)) {
		return 0
	}
	if (ne * 100) < ((nrows * ncols) * 35) {
		return 0
	}
	if (nend * 5) > (ne * 2) {
		return 0
	}
	if (nlong * 5) > ne {
		return 0
	}
	if prof == pfWhitespace {
		if (nw * 10) > (ne * 40) {
			return 0
		}
		score = 400
		if ncols >= 3 {
			score += 100
		}
		if tbNumCols(tb, k, 1, wd, et, tc, tw) >= 1 {
			score += 100
		}
		if tbHeadRows(tb, k, wd, et, tc, tw) >= 1 {
			score += 100
		}
		if nrows >= 4 {
			score += 50
		}
		if (ncols == 2) && ((nrows >= 3) && ((tbNumCols(tb, k, 1, wd, et, tc, tw) == 1) && ((nw * 10) <= (ne * 25)))) {
			score += 100
		}
		if score < 600 {
			return 0
		}
		return score
	}
	if (nw * 10) > (ne * 80) {
		return 0
	}
	if prof == pfPartial {
		return 800 + ((90 * tbTabularRows(tb, k, tc)) / tbMax(1, nrows))
	}
	return 750 + ((40 * tbTabularRows(tb, k, tc)) / tbMax(1, nrows))
}

func tbFirstRow(rw *port.Cells, nr int32, y0 int32) int32 {
	// The first row of a partial candidate: the first row whose centre is below the top rule y0, and the
	// tabular rows (at most three) directly above it, which are the header when the rule is the one under it.
	var ra int32 = 0
	var n int32 = 0
	for (ra < nr) && (((port.CellsAt(rw, (ra*rws)+6) + port.CellsAt(rw, (ra*rws)+7)) / 2) < y0) {
		ra += 1
	}
	for (ra > 0) && ((ra < nr) && ((n < 3) && ((port.CellsAt(rw, ((ra-1)*rws)+9) >= 2) && ((10 * (port.CellsAt(rw, (ra*rws)+2) - port.CellsAt(rw, ((ra-1)*rws)+2))) <= (24 * port.CellsAt(rw, (ra*rws)+3)))))) {
		ra -= 1
		n += 1
	}
	return ra
}

func tbPartialTry(wd *port.Cells, et *port.Cells, w0 int32, w1 int32, page int32, ex0 int32, ex1 int32, ya int32, yb int32, wl *port.Cells, rw *port.Cells, sg *port.Cells, ch *port.Cells, st *port.Cells, en *port.Cells, rmap *port.Cells, gm *port.Cells, gs *port.Cells, ry *port.Cells, pr *port.Cells, so *port.Cells, tb *port.Cells, tc *port.Cells, tw *port.Cells, tx *port.Cells) int32 {
	// One partial candidate: the words between the rules at ya and yb (and the tabular rows directly above ya),
	// columns from their channels; kept when it scores.
	var nr int32 = tbRows(wd, w0, w1, ex0-posTol, ya-9000, ex1+posTol, yb, wl, rw, sg)
	var ra int32 = tbFirstRow(rw, nr, ya)
	var nt int32 = tbRowsOf(tb, tbs)
	var c0 int32 = tbRowsOf(tc, tcs)
	var wl0 int32 = port.CellsLen(tw)
	var xl0 int32 = port.CellsLen(tx)
	if (nr - ra) >= 3 {
		var t int32 = tbTextGrid(wd, wl, rw, sg, ch, st, en, rmap, gm, gs, ry, pr, so, tb, tc, tw, tx, page, ra, nr, pfPartial, 850, 0, ex0, ya, ex1, yb)
		if t >= 0 {
			var sc int32 = tbScore(tb, t, wd, et, tc, tw)
			if sc == 0 {
				tbReject(tb, tc, tw, tx, nt, c0, wl0, xl0)
			} else {
				port.CellsSet(tb, (t*tbs)+6, sc)
			}
		}
	}
	return 0
}

func tbPartialPage(rm *port.Cells, page int32, wd *port.Cells, et *port.Cells, w0 int32, w1 int32, used *port.Cells, wl *port.Cells, rw *port.Cells, sg *port.Cells, ch *port.Cells, st *port.Cells, en *port.Cells, rmap *port.Cells, gm *port.Cells, gs *port.Cells, ry *port.Cells, pr *port.Cells, so *port.Cells, tb *port.Cells, tc *port.Cells, tw *port.Cells, tx *port.Cells) int32 {
	// Chains of horizontal rules of one extent (booktabs: top, mid, bottom) are partial candidates: the
	// words between the first and the last rule, columns from the channels of their text.
	var n int32 = tbRowsOf(rm, rls)
	var nh int32 = 0
	var i int32 = 0
	var j int32 = 0
	var cnt int32 = 0
	var ex0 int32 = 0
	var ex1 int32 = 0
	var m int32 = 0
	var last int32 = 0
	for (nh < n) && (port.CellsAt(rm, nh*rls) == 0) {
		nh += 1
	}
	port.CellsDrop(used, 0)
	for i < nh {
		port.CellsPush(used, 0)
		i += 1
	}
	i = 0
	for i < nh {
		if (port.CellsAt(used, i) == 0) && ((port.CellsAt(rm, (i*rls)+3) - port.CellsAt(rm, (i*rls)+2)) >= 3000) {
			cnt = 1
			ex0 = port.CellsAt(rm, (i*rls)+2)
			ex1 = port.CellsAt(rm, (i*rls)+3)
			last = port.CellsAt(rm, (i*rls)+1)
			port.CellsSet(used, i, 1)
			port.CellsPush(used, port.CellsAt(rm, (i*rls)+1))
			j = i + 1
			for (j < nh) && ((port.CellsAt(rm, (j*rls)+1) - last) <= 30000) {
				if port.CellsAt(used, j) == 0 {
					var a0 int32 = port.CellsAt(rm, (j*rls)+2)
					var a1 int32 = port.CellsAt(rm, (j*rls)+3)
					var ov int32 = tbMin(ex1, a1) - tbMax(ex0, a0)
					var lj int32 = a1 - a0
					if (lj >= 2000) && (((ov * 10) >= (lj * 6)) && ((ov * 10) >= ((ex1 - ex0) * 3))) {
						cnt += 1
						last = port.CellsAt(rm, (j*rls)+1)
						if a0 < ex0 {
							ex0 = a0
						}
						if a1 > ex1 {
							ex1 = a1
						}
						port.CellsSet(used, j, 1)
						port.CellsPush(used, port.CellsAt(rm, (j*rls)+1))
					}
				}
				j += 1
			}
			if cnt >= 2 {
				tbPartialTry(wd, et, w0, w1, page, ex0, ex1, port.CellsAt(rm, (i*rls)+1), last, wl, rw, sg, ch, st, en, rmap, gm, gs, ry, pr, so, tb, tc, tw, tx)
				if cnt >= 3 {
					m = nh
					for (m + 1) < port.CellsLen(used) {
						tbPartialTry(wd, et, w0, w1, page, ex0, ex1, port.CellsAt(used, m), port.CellsAt(used, m+1), wl, rw, sg, ch, st, en, rmap, gm, gs, ry, pr, so, tb, tc, tw, tx)
						m += 1
					}
				}
			}
			port.CellsDrop(used, nh)
		}
		i += 1
	}
	return 0
}

func tbBands(fl *port.Cells, so *port.Cells, bd *port.Cells) int32 {
	// The page's fills (`fl`) grouped into bands of one top and bottom (`bd`, stride 6: y0 y1 x0 x1 colour n),
	// in order of their tops. Answers how many bands.
	var n int32 = tbRowsOf(fl, 6)
	var i int32 = 0
	port.CellsDrop(so, 0)
	port.CellsDrop(bd, 0)
	for i < n {
		port.CellsPush(so, i)
		i += 1
	}
	tbSortIdx(so, fl, 6, 1, 0)
	i = 0
	for i < n {
		var f int32 = port.CellsAt(so, i)
		var x0 int32 = port.CellsAt(fl, f*6)
		var y0 int32 = port.CellsAt(fl, (f*6)+1)
		var x1 int32 = port.CellsAt(fl, (f*6)+2)
		var y1 int32 = port.CellsAt(fl, (f*6)+3)
		var nb int32 = tbRowsOf(bd, 6)
		if (nb > 0) && ((tbAbs(y0-port.CellsAt(bd, (nb-1)*6)) <= 150) && ((tbAbs(y1-port.CellsAt(bd, ((nb-1)*6)+1)) <= 150) && (x0 <= (port.CellsAt(bd, ((nb-1)*6)+3) + 300)))) {
			var lb int32 = (nb - 1) * 6
			if x0 < port.CellsAt(bd, lb+2) {
				port.CellsSet(bd, lb+2, x0)
			}
			if x1 > port.CellsAt(bd, lb+3) {
				port.CellsSet(bd, lb+3, x1)
			}
			port.CellsSet(bd, lb+5, port.CellsAt(bd, lb+5)+1)
		} else {
			port.CellsPush(bd, y0)
			port.CellsPush(bd, y1)
			port.CellsPush(bd, x0)
			port.CellsPush(bd, x1)
			port.CellsPush(bd, port.CellsAt(fl, (f*6)+4))
			port.CellsPush(bd, 1)
		}
		i += 1
	}
	return tbRowsOf(bd, 6)
}

func tbBandMember(bd *port.Cells, used *port.Cells, b0 int32, b1 int32, y int32) int32 {
	// The band of b0..b1 that belongs to the stack being built (used = 2) and whose top and bottom hold y.
	var i int32 = b0
	for i <= b1 {
		if (port.CellsAt(used, i) == 2) && ((y >= port.CellsAt(bd, i*6)) && (y <= port.CellsAt(bd, (i*6)+1))) {
			return i
		}
		i += 1
	}
	return -1
}

func tbShadedPage(fl *port.Cells, page int32, wd *port.Cells, et *port.Cells, w0 int32, w1 int32, bd *port.Cells, used *port.Cells, wl *port.Cells, rw *port.Cells, sg *port.Cells, ch *port.Cells, st *port.Cells, en *port.Cells, rmap *port.Cells, gm *port.Cells, gs *port.Cells, ry *port.Cells, pr *port.Cells, so *port.Cells, tb *port.Cells, tc *port.Cells, tw *port.Cells, tx *port.Cells) int32 {
	// Stacks of three or more bands of one extent, each starting where the one before ended or one row
	// later, with two colours or a gap (zebra), are shaded candidates: a band is a row (several baselines may
	// be in one), a baseline row that is in no band is a row of its own, columns from the channels.
	var nb int32 = tbBands(fl, so, bd)
	var i int32 = 0
	var j int32 = 0
	var cnt int32 = 0
	var last int32 = 0
	var ncol int32 = 0
	var gapseen int32 = 0
	port.CellsDrop(used, 0)
	for i < nb {
		port.CellsPush(used, 0)
		i += 1
	}
	i = 0
	for i < nb {
		if port.CellsAt(used, i) == 0 {
			var sx0 int32 = port.CellsAt(bd, (i*6)+2)
			var sx1 int32 = port.CellsAt(bd, (i*6)+3)
			var colour0 int32 = port.CellsAt(bd, (i*6)+4)
			cnt = 1
			last = i
			ncol = 1
			gapseen = 0
			port.CellsSet(used, i, 2)
			j = i + 1
			for (j < nb) && ((port.CellsAt(bd, j*6) - port.CellsAt(bd, (last*6)+1)) <= 3000) {
				if (port.CellsAt(used, j) == 0) && ((tbAbs(port.CellsAt(bd, (j*6)+2)-sx0) <= 400) && (tbAbs(port.CellsAt(bd, (j*6)+3)-sx1) <= 400)) {
					var g int32 = port.CellsAt(bd, j*6) - port.CellsAt(bd, (last*6)+1)
					var hj int32 = port.CellsAt(bd, (j*6)+1) - port.CellsAt(bd, j*6)
					if (g >= -150) && ((g * 5) <= (hj * 6)) {
						port.CellsSet(used, j, 2)
						cnt += 1
						if g > 150 {
							gapseen = 1
						}
						if port.CellsAt(bd, (j*6)+4) != colour0 {
							ncol = 2
						}
						last = j
					}
				}
				j += 1
			}
			if (cnt >= 3) && ((ncol == 2) || (gapseen == 1)) {
				var y0 int32 = port.CellsAt(bd, i*6)
				var y1 int32 = port.CellsAt(bd, (last*6)+1)
				var nr int32 = tbRows(wd, w0, w1, sx0, y0, sx1, y1, wl, rw, sg)
				var nt int32 = tbRowsOf(tb, tbs)
				var c0 int32 = tbRowsOf(tc, tcs)
				var wl0 int32 = port.CellsLen(tw)
				var xl0 int32 = port.CellsLen(tx)
				var r int32 = 0
				var trow int32 = -1
				var prevkey int32 = -999999
				var key int32 = 0
				if nr >= 3 {
					port.CellsDrop(rmap, 0)
					for r < nr {
						key = tbBandMember(bd, used, i, last, (port.CellsAt(rw, (r*rws)+6)+port.CellsAt(rw, (r*rws)+7))/2)
						if key < 0 {
							key = (0 - r) - 10
						}
						if key != prevkey {
							trow += 1
							prevkey = key
						}
						port.CellsPush(rmap, trow)
						r += 1
					}
					var t int32 = tbTextGrid(wd, wl, rw, sg, ch, st, en, rmap, gm, gs, ry, pr, so, tb, tc, tw, tx, page, 0, nr, pfShaded, 800, 1, sx0, y0, sx1, y1)
					if t >= 0 {
						var sc int32 = tbScore(tb, t, wd, et, tc, tw)
						if sc == 0 {
							tbReject(tb, tc, tw, tx, nt, c0, wl0, xl0)
						} else {
							port.CellsSet(tb, (t*tbs)+6, sc)
						}
					}
				}
			}
			j = i
			for j <= last {
				if port.CellsAt(used, j) == 2 {
					port.CellsSet(used, j, 1)
				}
				j += 1
			}
		}
		i += 1
	}
	return 0
}

func tbWhitespacePage(page int32, wd *port.Cells, et *port.Cells, w0 int32, w1 int32, wl *port.Cells, rw *port.Cells, sg *port.Cells, ch *port.Cells, st *port.Cells, en *port.Cells, rmap *port.Cells, gm *port.Cells, gs *port.Cells, ry *port.Cells, pr *port.Cells, so *port.Cells, tb *port.Cells, tc *port.Cells, tw *port.Cells, tx *port.Cells) int32 {
	// The rows of the whole page, in runs of rows that are cut in two or more chunks (a row of one chunk
	// goes in a run when a row of two follows it), each run of three such rows or more a whitespace candidate.
	var nr int32 = tbRows(wd, w0, w1, -2000000000, -2000000000, 2000000000, 2000000000, wl, rw, sg)
	var i int32 = 0
	var j int32 = 0
	var k int32 = 0
	var ntab int32 = 0
	var more int32 = 1
	for i < nr {
		if port.CellsAt(rw, (i*rws)+9) >= 2 {
			j = i
			ntab = 1
			more = 1
			for more == 1 {
				k = j + 1
				if k >= nr {
					more = 0
				} else {
					var gapk int32 = port.CellsAt(rw, (k*rws)+2) - port.CellsAt(rw, (j*rws)+2)
					var szk int32 = port.CellsAt(rw, (k*rws)+3)
					if (gapk * 10) > (szk * 30) {
						more = 0
					} else if port.CellsAt(rw, (k*rws)+9) >= 2 {
						j = k
						ntab += 1
					} else if (port.CellsAt(rw, (k*rws)+9) == 1) && ((k + 1) < nr) {
						if port.CellsAt(rw, ((k+1)*rws)+9) >= 2 {
							j = k
						} else {
							more = 0
						}
					} else {
						more = 0
					}
				}
			}
			for (j > i) && (port.CellsAt(rw, (j*rws)+9) < 2) {
				j -= 1
			}
			if ntab >= 3 {
				var nt int32 = tbRowsOf(tb, tbs)
				var c0 int32 = tbRowsOf(tc, tcs)
				var wl0 int32 = port.CellsLen(tw)
				var xl0 int32 = port.CellsLen(tx)
				var t int32 = tbTextGrid(wd, wl, rw, sg, ch, st, en, rmap, gm, gs, ry, pr, so, tb, tc, tw, tx, page, i, j+1, pfWhitespace, 0, 0, 2000000000, 2000000000, -2000000000, -2000000000)
				if t >= 0 {
					var sc int32 = tbScore(tb, t, wd, et, tc, tw)
					if sc == 0 {
						tbReject(tb, tc, tw, tx, nt, c0, wl0, xl0)
					} else {
						port.CellsSet(tb, (t*tbs)+6, sc)
					}
				}
			}
		} else {
			j = i
		}
		i = j + 1
	}
	return 0
}

func tbBodyLineOutside(ln *port.Cells, page int32, y0 int32, y1 int32, zlo int32, zhi int32) bool {
	// Is there a line, not claimed by a table, on `page` whose centre is in y0..y1 and outside the furniture
	// zones (above zlo, below zhi)?
	var n int32 = evidence.LnCount(ln)
	var l int32 = 0
	for l < n {
		if (evidence.LnGet(ln, l, evidence.LhPage()) == page) && (evidence.LnGet(ln, l, 15) == 0) {
			var cy int32 = (evidence.LnGet(ln, l, evidence.LhY0()) + evidence.LnGet(ln, l, evidence.LhY1())) / 2
			if (cy >= y0) && ((cy <= y1) && ((cy > zlo) && (cy < zhi))) {
				return 1 == 1
			}
		}
		l += 1
	}
	return 0 == 1
}

func tbSameColumns(tb *port.Cells, a int32, b int32, tx *port.Cells) bool {
	// The same number of columns, every boundary of b within 1/60 of the width of a's (at least 5 pt) of a's.
	var na int32 = port.CellsAt(tb, (a*tbs)+17)
	var nb int32 = port.CellsAt(tb, (b*tbs)+17)
	var xa int32 = port.CellsAt(tb, (a*tbs)+16)
	var xb int32 = port.CellsAt(tb, (b*tbs)+16)
	var i int32 = 0
	if na != nb {
		return 0 == 1
	}
	if na < 3 {
		return 0 == 1
	}
	var tol int32 = tbMax(500, (port.CellsAt(tx, xa+(na-1))-port.CellsAt(tx, xa))/60)
	for i < na {
		if tbAbs(port.CellsAt(tx, xa+i)-port.CellsAt(tx, xb+i)) > tol {
			return 0 == 1
		}
		i += 1
	}
	return 1 == 1
}

func tbWordSame(wd *port.Cells, et *port.Cells, a int32, b int32) bool {
	var n int32 = evidence.WdGet(wd, a, evidence.HdTlen())
	var sa int32 = evidence.WdGet(wd, a, evidence.HdTstart())
	var sb int32 = evidence.WdGet(wd, b, evidence.HdTstart())
	var i int32 = 0
	if n != evidence.WdGet(wd, b, evidence.HdTlen()) {
		return 0 == 1
	}
	for i < n {
		if port.CellsAt(et, sa+i) != port.CellsAt(et, sb+i) {
			return 0 == 1
		}
		i += 1
	}
	return 1 == 1
}

func tbRowSame(tb *port.Cells, a int32, ra int32, b int32, rb int32, tc *port.Cells, tw *port.Cells, wd *port.Cells, et *port.Cells) bool {
	// Does row ra of table a say, cell for cell and word for word, what row rb of table b says.
	var ca0 int32 = port.CellsAt(tb, (a*tbs)+9)
	var ca1 int32 = ca0 + port.CellsAt(tb, (a*tbs)+10)
	var cb0 int32 = port.CellsAt(tb, (b*tbs)+9)
	var cb1 int32 = cb0 + port.CellsAt(tb, (b*tbs)+10)
	var i int32 = ca0
	var j int32 = cb0
	var k int32 = 0
	for (i < ca1) && (port.CellsAt(tc, i*tcs) != ra) {
		i += 1
	}
	for (j < cb1) && (port.CellsAt(tc, j*tcs) != rb) {
		j += 1
	}
	for (i < ca1) && ((j < cb1) && ((port.CellsAt(tc, i*tcs) == ra) && (port.CellsAt(tc, j*tcs) == rb))) {
		if (port.CellsAt(tc, (i*tcs)+1) != port.CellsAt(tc, (j*tcs)+1)) || (port.CellsAt(tc, (i*tcs)+9) != port.CellsAt(tc, (j*tcs)+9)) {
			return 0 == 1
		}
		k = 0
		for k < port.CellsAt(tc, (i*tcs)+9) {
			if !tbWordSame(wd, et, port.CellsAt(tw, port.CellsAt(tc, (i*tcs)+8)+k), port.CellsAt(tw, port.CellsAt(tc, (j*tcs)+8)+k)) {
				return 0 == 1
			}
			k += 1
		}
		i += 1
		j += 1
	}
	return ((i >= ca1) || (port.CellsAt(tc, i*tcs) != ra)) && ((j >= cb1) || (port.CellsAt(tc, j*tcs) != rb))
}

func tbCaptionAgain(tb *port.Cells, a int32, b int32, wd *port.Cells, et *port.Cells, ln *port.Cells, tq *port.Cells) bool {
	// Does table b have a caption, and is it the label (keyword and number) of table a's?
	var qa int32 = port.CellsAt(tb, (a*tbs)+15)
	if qa == 0 {
		return 0 == 1
	}
	var wa int32 = evidence.LnGet(ln, port.CellsAt(tq, port.CellsAt(tb, (a*tbs)+14)), evidence.LhFirst())
	var wb int32 = evidence.LnGet(ln, port.CellsAt(tq, port.CellsAt(tb, (b*tbs)+14)), evidence.LhFirst())
	return tbWordSame(wd, et, wa, wb) && tbWordSame(wd, et, wa+1, wb+1)
}

func tbUnfoot(tb *port.Cells, a int32, tc *port.Cells) int32 {
	// A table that goes on has no foot on this page: its bold last row is a row.
	var b int32 = a * tbs
	var nrows int32 = port.CellsAt(tb, b+7)
	var nfoot int32 = port.CellsAt(tb, b+12)
	var cfirst int32 = port.CellsAt(tb, b+9)
	var cend int32 = cfirst + port.CellsAt(tb, b+10)
	var c int32 = cfirst
	for c < cend {
		if port.CellsAt(tc, c*tcs) >= (nrows - nfoot) {
			port.CellsSet(tc, (c*tcs)+10, 0)
		}
		c += 1
	}
	port.CellsSet(tb, b+12, 0)
	return 0
}

func tbLink(tb *port.Cells, tc *port.Cells, tw *port.Cells, tx *port.Cells, tq *port.Cells, wd *port.Cells, et *port.Cells, ln *port.Cells, pages *port.Cells) int32 {
	// Link the fragments of tables that go on across a page break (see the head of this section).
	var n int32 = tbRowsOf(tb, tbs)
	var j int32 = 1
	var a int32 = 0
	var head int32 = 0
	var h int32 = 0
	var ok int32 = 0
	var skip int32 = 0
	var span int32 = 0
	var r int32 = 0
	for j < n {
		a = j - 1
		head = a
		if port.CellsAt(tb, (a*tbs)+21) != 0 {
			head = port.CellsAt(tb, (a*tbs)+21) - 1
		}
		if (port.CellsAt(tb, (a*tbs)+0) == (port.CellsAt(tb, j*tbs) - 1)) && (port.CellsAt(tb, (a*tbs)+19) == 0) {
			ok = 1
			if !tbSameColumns(tb, a, j, tx) {
				ok = 0
			}
			if ok == 1 {
				var pg0 int32 = port.CellsAt(tb, a*tbs)
				var pj int32 = port.CellsAt(tb, j*tbs)
				var hpa int32 = model.PageH(pages, pg0-1)
				var hpj int32 = model.PageH(pages, pj-1)
				if tbBodyLineOutside(ln, pg0, port.CellsAt(tb, (a*tbs)+4), hpa, (hpa*8)/100, (hpa*92)/100) {
					ok = 0
				}
				if tbBodyLineOutside(ln, pj, 0, port.CellsAt(tb, (j*tbs)+2), (hpj*8)/100, (hpj*92)/100) {
					ok = 0
				}
			}
			if (ok == 1) && (port.CellsAt(tb, (j*tbs)+15) > 0) {
				if !tbCaptionAgain(tb, head, j, wd, et, ln, tq) {
					ok = 0
				}
			}
			skip = 0
			if (ok == 1) && (port.CellsAt(tb, (j*tbs)+11) > 0) {
				h = port.CellsAt(tb, (head*tbs)+11)
				if h != port.CellsAt(tb, (j*tbs)+11) {
					ok = 0
				} else {
					r = 0
					for r < h {
						if !tbRowSame(tb, head, r, j, r, tc, tw, wd, et) {
							ok = 0
						}
						r += 1
					}
					skip = h
				}
			}
			if ok == 1 {
				port.CellsSet(tb, (a*tbs)+19, j+1)
				port.CellsSet(tb, (j*tbs)+20, skip)
				port.CellsSet(tb, (j*tbs)+21, head+1)
				span = (port.CellsAt(tb, j*tbs) - port.CellsAt(tb, head*tbs)) + 1
				port.CellsSet(tb, (head*tbs)+18, span)
				tbUnfoot(tb, a, tc)
			}
		}
		j += 1
	}
	return 0
}

func tbCellAt(tc *port.Cells, cfirst int32, cend int32, row int32, col int32) int32 {
	// The live cell whose rows and columns cover (row, col), -1 when none does.
	var c int32 = cfirst
	for c < cend {
		var cb int32 = c * tcs
		if (port.CellsAt(tc, cb+12) & 1) == 0 {
			if (port.CellsAt(tc, cb) <= row) && (row < (port.CellsAt(tc, cb) + port.CellsAt(tc, cb+2))) {
				if (port.CellsAt(tc, cb+1) <= col) && (col < (port.CellsAt(tc, cb+1) + port.CellsAt(tc, cb+3))) {
					return c
				}
			}
		}
		c += 1
	}
	return -1
}

func tbHeaderSpans(tb *port.Cells, k int32, tc *port.Cells) int32 {
	// Text-based tables have no rules to say where a header cell spans: a header cell whose cell below it is
	// empty spans down (the empty cell is absorbed: flag 1), and a header cell followed by empty cells over cells
	// with text spans across them. Only header rows with a header row below them are looked at.
	var b int32 = k * tbs
	var nhead int32 = port.CellsAt(tb, b+11)
	var ncols int32 = port.CellsAt(tb, b+8)
	var cfirst int32 = port.CellsAt(tb, b+9)
	var cend int32 = cfirst + port.CellsAt(tb, b+10)
	var c int32 = cfirst
	var rs int32 = 1
	var j int32 = 0
	var y int32 = -1
	var more int32 = 1
	if nhead < 2 {
		return 0
	}
	for c < cend {
		var cb int32 = c * tcs
		var r int32 = port.CellsAt(tc, cb)
		var col int32 = port.CellsAt(tc, cb+1)
		if (r < (nhead - 1)) && (((port.CellsAt(tc, cb+12) & 1) == 0) && (port.CellsAt(tc, cb+9) > 0)) {
			rs = 1
			more = 1
			for (more == 1) && ((r + rs) < nhead) {
				y = tbCellAt(tc, cfirst, cend, r+rs, col)
				if (y >= 0) && ((port.CellsAt(tc, y*tcs) == (r + rs)) && ((port.CellsAt(tc, (y*tcs)+1) == col) && ((port.CellsAt(tc, (y*tcs)+3) == port.CellsAt(tc, cb+3)) && (port.CellsAt(tc, (y*tcs)+9) == 0)))) {
					port.CellsSet(tc, (y*tcs)+12, 1)
					rs += 1
				} else {
					more = 0
				}
			}
			if rs > 1 {
				port.CellsSet(tc, cb+2, rs)
			}
			if port.CellsAt(tc, cb+3) == 1 {
				j = col + 1
				more = 1
				for (more == 1) && (j < ncols) {
					var e int32 = tbCellAt(tc, cfirst, cend, r, j)
					var under int32 = tbCellAt(tc, cfirst, cend, r+1, j)
					if (e >= 0) && (under >= 0) {
						if (port.CellsAt(tc, (e*tcs)+1) == j) && ((port.CellsAt(tc, (e*tcs)+3) == 1) && ((port.CellsAt(tc, (e*tcs)+9) == 0) && (port.CellsAt(tc, (under*tcs)+9) > 0))) {
							port.CellsSet(tc, (e*tcs)+12, 1)
							port.CellsSet(tc, cb+3, port.CellsAt(tc, cb+3)+1)
							j += 1
						} else {
							more = 0
						}
					} else {
						more = 0
					}
				}
			}
		}
		c += 1
	}
	return 0
}

func tbFinish(tb *port.Cells, k int32, wd *port.Cells, et *port.Cells, tc *port.Cells, tw *port.Cells, ln *port.Cells, l0 int32, l1 int32, tq *port.Cells) int32 {
	// What the cells of table k say once they are placed (SPEC 10.5, 10.10): the header rows, the footer,
	// which cells are header cells (`col` in the header, `row` in the footer), each cell's alignment, the caption.
	var b int32 = k * tbs
	var nrows int32 = port.CellsAt(tb, b+7)
	var cfirst int32 = port.CellsAt(tb, b+9)
	var cend int32 = cfirst + port.CellsAt(tb, b+10)
	var nhead int32 = tbHeadRows(tb, k, wd, et, tc, tw)
	var nfoot int32 = tbFootRows(tb, k, nhead, wd, et, tc, tw)
	var c int32 = cfirst
	port.CellsSet(tb, b+11, nhead)
	port.CellsSet(tb, b+12, nfoot)
	for c < cend {
		var r int32 = port.CellsAt(tc, c*tcs)
		if r < nhead {
			port.CellsSet(tc, (c*tcs)+10, 1)
		}
		if r >= (nrows - nfoot) {
			port.CellsSet(tc, (c*tcs)+10, 2)
		}
		c += 1
	}
	if port.CellsAt(tb, b+5) != pfRuled {
		tbHeaderSpans(tb, k, tc)
	}
	tbAligns(tb, k, wd, tc, tw)
	tbCaption(tb, k, wd, et, ln, l0, l1, tq)
	return 0
}

func TbBuild(wd *port.Cells, ln *port.Cells, et *port.Cells, pa *port.Cells, np int32, tb *port.Cells, tc *port.Cells, tw *port.Cells, tq *port.Cells, tx *port.Cells, s0 *port.Cells, s1 *port.Cells, s2 *port.Cells, s3 *port.Cells, s4 *port.Cells, s5 *port.Cells, s6 *port.Cells, s7 *port.Cells, s8 *port.Cells, s9 *port.Cells, s10 *port.Cells, s11 *port.Cells, s12 *port.Cells, s13 *port.Cells, s14 *port.Cells, s15 *port.Cells, s16 *port.Cells, s17 *port.Cells, s18 *port.Cells, pages *port.Cells) int32 {
	// Find the tables of every page and claim their lines. `tb tc tw tq tx` are emptied first; s0..s18 are
	// scratch: rules, merged rules, fills, a sort order, x and y boundaries, the grid, word pairs, a copy of tb
	// rows, flags, the page's words, rows and chunks, channels, two coordinate lists, the row map, spans and
	// row extents (one name each in the calls below). Answers the number of tables.
	var nw int32 = evidence.WdCount(wd)
	var nl int32 = evidence.LnCount(ln)
	var nq int32 = evidence.PaCount(pa)
	var p int32 = 1
	var wi int32 = 0
	var wj int32 = 0
	var li int32 = 0
	var lj int32 = 0
	var qi int32 = 0
	var qj int32 = 0
	var t0 int32 = 0
	var k int32 = 0
	port.CellsDrop(tb, 0)
	port.CellsDrop(tc, 0)
	port.CellsDrop(tw, 0)
	port.CellsDrop(tq, 0)
	port.CellsDrop(tx, 0)
	for p <= np {
		for (wi < nw) && (evidence.WdGet(wd, wi, evidence.HdPage()) < p) {
			wi += 1
		}
		wj = wi
		for (wj < nw) && (evidence.WdGet(wd, wj, evidence.HdPage()) == p) {
			wj += 1
		}
		for (li < nl) && (evidence.LnGet(ln, li, evidence.LhPage()) < p) {
			li += 1
		}
		lj = li
		for (lj < nl) && (evidence.LnGet(ln, lj, evidence.LhPage()) == p) {
			lj += 1
		}
		for (qi < nq) && (evidence.PaGet(pa, qi, evidence.PfPage()) < p) {
			qi += 1
		}
		qj = qi
		for (qj < nq) && (evidence.PaGet(pa, qj, evidence.PfPage()) == p) {
			qj += 1
		}
		t0 = tbRowsOf(tb, tbs)
		if (wj - wi) > 0 {
			tbCollect(pa, qi, qj, s0, s2)
			if tbRowsOf(s0, rls) <= maxRules {
				tbMergeRules(s0, s1, s3, s9)
				tbRuledPage(s1, p, s4, s5, s6, tb, tc, wd, wi, wj, s7, s3, tw, tx)
				tbPartialPage(s1, p, wd, et, wi, wj, s9, s10, s11, s12, s13, s14, s15, s16, s6, s17, s18, s7, s3, tb, tc, tw, tx)
			}
			if tbRowsOf(s2, 6) <= maxRules {
				tbShadedPage(s2, p, wd, et, wi, wj, s8, s9, s10, s11, s12, s13, s14, s15, s16, s6, s17, s18, s7, s3, tb, tc, tw, tx)
			}
			tbWhitespacePage(p, wd, et, wi, wj, s10, s11, s12, s13, s14, s15, s16, s6, s17, s18, s7, s3, tb, tc, tw, tx)
			tbSelect(tb, t0, s3, s9, s8)
			k = t0
			for k < tbRowsOf(tb, tbs) {
				tbFinish(tb, k, wd, et, tc, tw, ln, li, lj, tq)
				k += 1
			}
			tbClaim(tb, t0, ln, li, lj)
		}
		wi = wj
		li = lj
		qi = qj
		p += 1
	}
	tbLink(tb, tc, tw, tx, tq, wd, et, ln, pages)
	return tbRowsOf(tb, tbs)
}
